INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('aba085f1-0a92-44a7-904a-5aac35c0aa40'::uuid, 'card_description', 'Built around 3400 BC, Quanterness Chambered Cairn on Orkney is now a grass-covered mound. Excavation found the remains of 157 people, and an Iron Age roundhouse built into the cairn.', 'A 3400 BC burial cairn that held the remains of 157 people. An Iron Age roundhouse was later built right into the ancient tomb around 700 BC.', 'teaser-card-s005-rollback:aba085f1-0a92-44a7-904a-5aac35c0aa40:card_description', 'rollback of teaser-card-s005: card_description ''A 3400 BC burial cairn that held the remains of 157 people. An Iron Age roundhouse was later built right into the ancient tomb around 700 BC.'' restored on Quanterness Chambered Cairn', '46ac2c6cd89b7a172a28b3fe6636e22d0d3a3b8fa7a8c29079f0ecf655391431|eb34aa2936579130dcab6352c6f69db928d057e2d291dd566d1af6e22e07296b|eb34aa2936579130dcab6352c6f69db928d057e2d291dd566d1af6e22e07296b', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Built around 3400 BC, Quanterness Chambered Cairn on Orkney is now a grass-covered mound. Excavation found the remains of 157 people, and an Iron Age roundhouse built into the cairn."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the cairn was built around 3400 BC [S8]; Quanterness Chambered Cairn is on Orkney [S1]; it is now a grass-covered mound [S5]; excavation found the remains of 157 people [S4]; excavation found an Iron Age roundhouse built into the cairn [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Quanterness Chambered Cairn is a Neolithic chambered burial cairn (tomb) on Orkney, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Quanterness_chambered_cairn]; It was built around 3400 BC [SUPPORTED: https://en.wikipedia.org/wiki/Quanterness_chambered_cairn]; It is now a grass-covered mound [SUPPORTED: https://en.wikipedia.org/wiki/Quanterness_chambered_cairn]; Excavation found the remains of 157 people [SUPPORTED: https://en.wikipedia.org/wiki/Quanterness_chambered_cairn]; Excavation found an Iron Age roundhouse built into the cairn [SUPPORTED: https://en.wikipedia.org/wiki/Quanterness_chambered_cairn]"}]'::jsonb),
    ('ac28b46b-542e-48b7-adf9-32da0efd74c1'::uuid, 'card_description', 'In 1870, work on the railroad from Ancon to Pasamayo uncovered the first large ancient tombs of Ancon Archaeological Site, a vast pre-Hispanic necropolis of countless funerary sites.', 'An 8000 BC site with over 10,000 burials spanning pre-ceramic through Inca periods. The dry climate mummified bodies naturally, preserving textiles and hair.', 'teaser-card-s005-rollback:ac28b46b-542e-48b7-adf9-32da0efd74c1:card_description', 'rollback of teaser-card-s005: card_description ''An 8000 BC site with over 10,000 burials spanning pre-ceramic through Inca periods. The dry climate mummified bodies naturally, preserving textiles and hair.'' restored on Ancon Archaeological Site', '212c05f70e89d72db91b8d477fddb77d68c5d9a053a3ac7fbcd92f0d93e59564|78db7c52d90d9171825689c7775ab7be2ee819ebc6264110aeca85461bbea31d|78db7c52d90d9171825689c7775ab7be2ee819ebc6264110aeca85461bbea31d', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In 1870, work on the railroad from Ancon to Pasamayo uncovered the first large ancient tombs of Ancon Archaeological Site, a vast pre-Hispanic necropolis of countless funerary sites."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "in 1870 the first large ancient tombs were uncovered [S5]; they were uncovered during work on the railroad from Ancon to Pasamayo [S5]; the site has a vast necropolis of the pre-Hispanic era [S2]; the necropolis has countless funerary sites [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Ancon Archaeological Site is a vast pre-Hispanic necropolis in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Ancon_(archaeological_site)]; The site is in Peru (Ancon) [SUPPORTED: https://en.wikipedia.org/wiki/Ancon_(archaeological_site)]; The necropolis comprises countless funerary sites [SUPPORTED: https://en.wikipedia.org/wiki/Ancon_(archaeological_site)]; The first large ancient tombs were uncovered in 1870 [SUPPORTED: https://en.wikipedia.org/wiki/Ancon_(archaeological_site)]; They were uncovered by work on the railroad from Ancon to Pasamayo [SUPPORTED: https://en.wikipedia.org/wiki/Ancon_(archaeological_site)]"}]'::jsonb),
    ('ac2c74ff-d861-4609-8589-67a8c3eceb3c'::uuid, 'card_description', 'Believed to be some 5,000 years old, Ballynoe Stone Circle is a ring of 50 or more small upright stones, around 35 m across. Inside, excavation found a long cairn with cists at both ends.', 'A Neolithic stone circle 35 metres wide with over 50 upright stones. A mound inside the ring held cremated remains, hinting at rituals spanning millennia.', 'teaser-card-s005-rollback:ac2c74ff-d861-4609-8589-67a8c3eceb3c:card_description', 'rollback of teaser-card-s005: card_description ''A Neolithic stone circle 35 metres wide with over 50 upright stones. A mound inside the ring held cremated remains, hinting at rituals spanning millennia.'' restored on Ballynoe Stone Circle', '330a9aa4640ead94379dc2f60cef58d1cc489c0bbfcd2a867c9d2b8b2862165a|4ab42fbdb4290b074af5ddec14b08bb8543a95c13f81ffea29e14da68cf76fad|4ab42fbdb4290b074af5ddec14b08bb8543a95c13f81ffea29e14da68cf76fad', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Believed to be some 5,000 years old, Ballynoe Stone Circle is a ring of 50 or more small upright stones, around 35 m across. Inside, excavation found a long cairn with cists at both ends."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Ballynoe Stone Circle is believed to be some 5,000 years old [S2]; it is a ring of 50 or more small upright stones [S4]; the circle is around 35 m across [S4]; excavation found a long cairn inside the circle [S6]; the cairn had cists at both ends [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Ballynoe Stone Circle is a stone circle in Northern Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Ballynoe_stone_circle]; It is believed to be some 5,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Ballynoe_stone_circle]; It is a ring of 50 or more small upright stones [SUPPORTED: https://en.wikipedia.org/wiki/Ballynoe_stone_circle]; The circle is around 35 m across [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=657]; Excavation found a long cairn inside the circle [SUPPORTED: https://en.wikipedia.org/wiki/Ballynoe_stone_circle]; The long cairn had cists at both ends [SUPPORTED: https://en.wikipedia.org/wiki/Ballynoe_stone_circle]"}]'::jsonb),
    ('ac94e596-0960-45e2-acc5-bba445decae9'::uuid, 'card_description', 'On a heavily forested hill above Abergele, the Iron Age hillfort of Castell Cawr overlooks the River Clwyd. On the hillside, the workings of a Roman lead mine were identified in 1860.', 'Densely forested hill 189 metres above Abergele in Conwy, with a hilltop fort overlooking the River Clwyd. Caves below host rare lesser horseshoe bat colonies -- wildlife and antiquity share the hill.', 'teaser-card-s005-rollback:ac94e596-0960-45e2-acc5-bba445decae9:card_description', 'rollback of teaser-card-s005: card_description ''Densely forested hill 189 metres above Abergele in Conwy, with a hilltop fort overlooking the River Clwyd. Caves below host rare lesser horseshoe bat colonies -- wildlife and antiquity share the hill.'' restored on Castell Cawr', 'ab46c87716245288c0258248578ae32784042673240ebae623857f35e32cc16d|30a8e22ffa19eba5ae699dd762cea72a127c6a02f1e5d2951c5ca53a312ea9cd|30a8e22ffa19eba5ae699dd762cea72a127c6a02f1e5d2951c5ca53a312ea9cd', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a heavily forested hill above Abergele, the Iron Age hillfort of Castell Cawr overlooks the River Clwyd. On the hillside, the workings of a Roman lead mine were identified in 1860."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is on a heavily forested hill above Abergele [S1]; Castell Cawr is an Iron Age hillfort [S2]; the hillfort overlooks the River Clwyd [S2]; the workings of a Roman lead mine were identified on the hillside [S5]; the lead mine workings were identified in 1860 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Castell Cawr is an Iron Age hillfort, on a hill above Abergele in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Cawr]; The hill is heavily forested and lies above Abergele [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Cawr]; The hillfort overlooks the River Clwyd [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Cawr]; The workings of a Roman lead mine were identified on the hillside [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Cawr]; The lead mine workings were identified in 1860 [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Cawr]"}]'::jsonb),
    ('ad2b103b-1296-40b2-895d-98f7dc8558be'::uuid, 'card_description', 'On vertical rock faces beside the Daegokcheon stream, the Bangudae Petroglyphs portray whaling in vivid detail: 312 engravings, among them humpback, gray and sperm whales.', 'In total, 312 engravings can be seen, of which 200 figures are accounted for as the animals and 23 are unidentified creatures.', 'teaser-card-s005-rollback:ad2b103b-1296-40b2-895d-98f7dc8558be:card_description', 'rollback of teaser-card-s005: card_description ''In total, 312 engravings can be seen, of which 200 figures are accounted for as the animals and 23 are unidentified creatures.'' restored on Bangudae Petroglyphs', 'd005a35d5ec06bf6dceb7de273b46de83c3eb4c650b2a88faf103548041a3d48|5d173e75f2621abfc4a9cf4c3ca62fce99f736267dcd53f498ce212746fa66da|5d173e75f2621abfc4a9cf4c3ca62fce99f736267dcd53f498ce212746fa66da', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On vertical rock faces beside the Daegokcheon stream, the Bangudae Petroglyphs portray whaling in vivid detail: 312 engravings, among them humpback, gray and sperm whales."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the petroglyphs are on vertical rock faces [S1]; the rock faces are beside the Daegokcheon stream [S1]; the petroglyphs portray whaling in vivid detail [S3]; there are 312 engravings [S6]; the engravings include humpback, gray and sperm whales [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Bangudae Petroglyphs are prehistoric rock engravings on vertical rock faces beside the Daegokcheon stream in South Korea [SUPPORTED: https://en.wikipedia.org/wiki/Bangudae_Petroglyphs]; The petroglyphs portray whaling in vivid detail [SUPPORTED: https://en.wikipedia.org/wiki/Bangudae_Petroglyphs]; There are 312 engravings [SUPPORTED: https://en.wikipedia.org/wiki/Bangudae_Petroglyphs]; Among the engravings are humpback whales [SUPPORTED: https://en.wikipedia.org/wiki/Bangudae_Petroglyphs]; Among the engravings are gray whales [SUPPORTED: https://en.wikipedia.org/wiki/Bangudae_Petroglyphs]; Among the engravings are sperm whales [SUPPORTED: https://en.wikipedia.org/wiki/Bangudae_Petroglyphs]"}]'::jsonb),
    ('ad2eb54f-98a3-4299-8cd5-56e3ddc0b48f'::uuid, 'card_description', 'East of the acropolis of Selinus, Temple E lifts Doric columns 10.19 metres high, still traced with stucco. An inscription on a votive stela points to Hera; some scholars argue Aphrodite.', 'Mid-6th-century BC Doric temple on Selinus''s east hill, raised on the foundations of an earlier structure. Debate over its dedication—Hera or Aphrodite—remains unresolved.', 'teaser-card-s005-rollback:ad2eb54f-98a3-4299-8cd5-56e3ddc0b48f:card_description', 'rollback of teaser-card-s005: card_description "Mid-6th-century BC Doric temple on Selinus''s east hill, raised on the foundations of an earlier structure. Debate over its dedication—Hera or Aphrodite—remains unresolved." restored on Temple E, Selinus', 'fb81603b1d0b48a1ce39b9e1e8381effe375e6f63c272c50f0e988b42d639f0a|beab3aed5390f83ff722d72299c6161edb89d5ab775ac185fa4cbf0930911827|beab3aed5390f83ff722d72299c6161edb89d5ab775ac185fa4cbf0930911827', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "East of the acropolis of Selinus, Temple E lifts Doric columns 10.19 metres high, still traced with stucco. An inscription on a votive stela points to Hera; some scholars argue Aphrodite."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Temple E stands east of the acropolis of Selinus [S2]; its columns are Doric [S1]; the columns are 10.19 metres high [S8]; the columns still bear traces of stucco [S8]; an inscription on a votive stela points to Hera [S3]; some scholars argue it was dedicated to Aphrodite [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Temple E is a Greek temple at Selinus (Sicily, Italy), standing east of the acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Temple_E_(Selinus)]; Temple E has Doric columns (it is of the Doric order) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_E_(Selinus)]; Its columns are 10.19 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Temple_E_(Selinus)]; The columns still bear traces of stucco [SUPPORTED: https://en.wikipedia.org/wiki/Temple_E_(Selinus)]; An inscription on a votive stela points to Hera as the temple''s deity [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Temple_E_(Selinus)]; Some scholars argue the temple was dedicated to Aphrodite [SUPPORTED: https://en.wikipedia.org/wiki/Temple_E_(Selinus)]"}]'::jsonb),
    ('ae28d423-c02b-44be-b78d-7d65c99f3c3b'::uuid, 'card_description', 'About 30 Bronze Age round barrows rise on Cranborne Chase at Oakley Down Barrow Cemetery. Inside lay cremations in urns and cists, beads of amber, glass and faience, and bronze daggers.', 'Roughly 30 barrows cluster near a Neolithic mound on Cranborne Chase, dating from 2500 to 800 BC. The earlier earthwork likely shaped where Bronze Age communities chose to inter their dead.', 'teaser-card-s005-rollback:ae28d423-c02b-44be-b78d-7d65c99f3c3b:card_description', 'rollback of teaser-card-s005: card_description ''Roughly 30 barrows cluster near a Neolithic mound on Cranborne Chase, dating from 2500 to 800 BC. The earlier earthwork likely shaped where Bronze Age communities chose to inter their dead.'' restored on Oakley Down Barrow Cemetery', 'c97b77c9678dfa27c84c048ecd99be8055ac7dea52843dbdb3dd856ffdfdfd39|83f78f4a9346da98a03143d1dce2050863b8db4014b63dd024ceebad1bb6bbbc|83f78f4a9346da98a03143d1dce2050863b8db4014b63dd024ceebad1bb6bbbc', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "About 30 Bronze Age round barrows rise on Cranborne Chase at Oakley Down Barrow Cemetery. Inside lay cremations in urns and cists, beads of amber, glass and faience, and bronze daggers."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "there are about 30 barrows [S3]; they are Bronze Age round barrows [S1]; they are on Cranborne Chase [S1]; the barrows contained cremations in urns and cists [S5]; grave goods included beads of amber, glass and faience [S6]; grave goods included bronze daggers [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Oakley Down Barrow Cemetery is a cemetery of round barrows on Cranborne Chase (England) [SUPPORTED: https://en.wikipedia.org/wiki/Oakley_Down_Barrow_Cemetery]; The barrows date to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Oakley_Down_Barrow_Cemetery]; There are about 30 barrows [SUPPORTED: https://en.wikipedia.org/wiki/Oakley_Down_Barrow_Cemetery]; The barrows contained cremations in urns and cists [SUPPORTED: https://en.wikipedia.org/wiki/Oakley_Down_Barrow_Cemetery]; Grave goods included beads of amber, glass and faience [SUPPORTED: https://en.wikipedia.org/wiki/Oakley_Down_Barrow_Cemetery]; Grave goods included bronze daggers [SUPPORTED: https://en.wikipedia.org/wiki/Oakley_Down_Barrow_Cemetery]"}]'::jsonb),
    ('ae3b5deb-3b9c-42ec-8610-445c99f5b1a8'::uuid, 'card_description', 'Less than 3 kilometres from Stonehenge, the Iron Age hillfort of Vespasian''s Camp carries a Roman general''s name, given in the 16th century, yet no evidence suggests he ever came here.', 'Less than 3 km from Stonehenge, built beside the ceremonial Stonehenge Avenue, this ~800 BC hillfort has the River Avon as its southern boundary — a naturally defensible position on three sides.', 'teaser-card-s005-rollback:ae3b5deb-3b9c-42ec-8610-445c99f5b1a8:card_description', 'rollback of teaser-card-s005: card_description ''Less than 3 km from Stonehenge, built beside the ceremonial Stonehenge Avenue, this ~800 BC hillfort has the River Avon as its southern boundary — a naturally defensible position on three sides.'' restored on Vespasian''s Camp', 'db84b637cbcefe9bb5a2f86621e09546168576e45091960d1a8d4e6c064e4dc8|ea1727a2b1895bfe0b78f596b9622ed54e8efebbc30c88c1c8c24bbdb070b722|ea1727a2b1895bfe0b78f596b9622ed54e8efebbc30c88c1c8c24bbdb070b722', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Less than 3 kilometres from Stonehenge, the Iron Age hillfort of Vespasian''s Camp carries a Roman general''s name, given in the 16th century, yet no evidence suggests he ever came here."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is less than 3 kilometres from Stonehenge [S2]; Vespasian''s Camp is an Iron Age hillfort [S1]; it carries the name of a Roman general [S4, S5]; the name was given in the 16th century [S4]; no evidence suggests the general ever came to the hillfort [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Vespasian''s Camp is an Iron Age hillfort (in Wiltshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Vespasian%27s_Camp]; It lies less than 3 kilometres from Stonehenge [SUPPORTED: https://en.wikipedia.org/wiki/Vespasian%27s_Camp]; The hillfort carries the name of a Roman general (Vespasian) [SUPPORTED: https://en.wikipedia.org/wiki/Vespasian%27s_Camp]; The name was given in the 16th century [SUPPORTED: https://en.wikipedia.org/wiki/Vespasian%27s_Camp]; No evidence suggests Vespasian ever came to the site [SUPPORTED: https://en.wikipedia.org/wiki/Vespasian%27s_Camp]"}]'::jsonb),
    ('af860ca9-85af-4444-8f71-8e56282d7cb4'::uuid, 'card_description', 'Close to Lynmouth in Devon, a hillside spur juts above the steep valley of the East Lyn River, and on that promontory lies Myrtlebury, an Iron Age enclosure or spur hill fort.', 'Myrtlebury is an Iron Age enclosure or ''spur'' hill fort situated close to Lynmouth in Devon.', 'teaser-card-s005-rollback:af860ca9-85af-4444-8f71-8e56282d7cb4:card_description', 'rollback of teaser-card-s005: card_description "Myrtlebury is an Iron Age enclosure or ''spur'' hill fort situated close to Lynmouth in Devon." restored on Myrtlebury', 'f341dc28f1a9133dcc9964dbc1d10a3b6963ffc6390a277953bb258f58ce3896|7c5292f07517722bebac1cafd470d007637e1e759d8f725da950e74f218d047a|7c5292f07517722bebac1cafd470d007637e1e759d8f725da950e74f218d047a', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Close to Lynmouth in Devon, a hillside spur juts above the steep valley of the East Lyn River, and on that promontory lies Myrtlebury, an Iron Age enclosure or spur hill fort."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Myrtlebury lies close to Lynmouth [S1]; Myrtlebury is in Devon [S1]; it sits on a hillside spur or promontory [S2]; the spur rises above the steep valley of the East Lyn River [S2]; Myrtlebury is an Iron Age enclosure or spur hill fort [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Myrtlebury is an Iron Age enclosure or spur hill fort close to Lynmouth in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Myrtlebury]; The site dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Myrtlebury]; It lies on a hillside forming a spur or promontory [SUPPORTED: https://en.wikipedia.org/wiki/Myrtlebury]; The spur rises above the steep valley of the East Lyn River [SUPPORTED: https://en.wikipedia.org/wiki/Myrtlebury]; Lynmouth is in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Myrtlebury]"}]'::jsonb),
    ('afd94b96-449f-4289-bb65-f4e576b9555b'::uuid, 'card_description', 'On the southern side of Castle Hill, the small Iron Age fort of Castle Old Fort yielded flint arrowheads, Roman pottery and Roman coins of Otho, Domitian and Nero, as Robert Plot reported.', 'Promontory fort in Stonnall whose interior is now occupied by a house. Positioned on Castle Hill, its occupants could monitor an ancient highway running below -- a uniquely inhabited ancient monument.', 'teaser-card-s005-rollback:afd94b96-449f-4289-bb65-f4e576b9555b:card_description', 'rollback of teaser-card-s005: card_description ''Promontory fort in Stonnall whose interior is now occupied by a house. Positioned on Castle Hill, its occupants could monitor an ancient highway running below -- a uniquely inhabited ancient monument.'' restored on Castle Old Fort', '59cde722842aaf2015e84b3626163ae2105a454ab8e237e41e0256615e69e760|5949cc3e2fc16d0f8b5d448440ba38ce98c5e3d6508fd7198e6c3b748619422b|5949cc3e2fc16d0f8b5d448440ba38ce98c5e3d6508fd7198e6c3b748619422b', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the southern side of Castle Hill, the small Iron Age fort of Castle Old Fort yielded flint arrowheads, Roman pottery and Roman coins of Otho, Domitian and Nero, as Robert Plot reported."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the fort is on the southern side of Castle Hill [S2]; Castle Old Fort is a small Iron Age fort [S1]; finds included flint arrowheads [S3]; finds included Roman pottery [S3]; finds included Roman coins of Otho, Domitian and Nero [S3]; Robert Plot reported these finds [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Castle Old Fort is a small Iron Age fort (in England) [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Old_Fort]; It lies on the southern side of Castle Hill [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Old_Fort]; The finds were reported by Robert Plot [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Old_Fort]; The fort yielded flint arrowheads [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Old_Fort]; The fort yielded Roman pottery [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Old_Fort]; The fort yielded Roman coins of Otho, Domitian and Nero [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Old_Fort]"}]'::jsonb),
    ('b0138ff7-a0fc-49ca-9df7-35d97a6e36b6'::uuid, 'card_description', 'The foundations of the Hekatompedon Temple on the Acropolis of Athens have disappeared, but scholars assign it painted pediments: lionesses tearing apart a bull, Herakles fighting Triton.', 'Built 570–550 BC on the Acropolis and named ''hundred feet long'' — yet stretching 46 metres. Deliberately demolished by the Athenians in 490 BC, after their victory over the Persians at Marathon.', 'teaser-card-s005-rollback:b0138ff7-a0fc-49ca-9df7-35d97a6e36b6:card_description', 'rollback of teaser-card-s005: card_description "Built 570–550 BC on the Acropolis and named ''hundred feet long'' — yet stretching 46 metres. Deliberately demolished by the Athenians in 490 BC, after their victory over the Persians at Marathon." restored on Hekatompedon Temple', '65d1b81c05261b63c8857e2e05c607f0804c1bcd6cca119b11a7a2a4d77b356b|d1fdf4416822d89479b86c882122e81422e4434cb01f32e601ed1672bae53232|d1fdf4416822d89479b86c882122e81422e4434cb01f32e601ed1672bae53232', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The foundations of the Hekatompedon Temple on the Acropolis of Athens have disappeared, but scholars assign it painted pediments: lionesses tearing apart a bull, Herakles fighting Triton."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Hekatompedon Temple was on the Acropolis of Athens [S1]; its foundations have disappeared [S4]; scholars assign surviving elements to the temple [S4]; its pediments were painted [S5]; a pediment showed lionesses tearing apart a bull [S6]; a pediment showed Herakles fighting Triton [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Hekatompedon Temple was a temple on the Acropolis of Athens, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Hekatompedon]; The foundations of the Hekatompedon Temple have disappeared [SUPPORTED: https://en.wikipedia.org/wiki/Hekatompedon]; Scholars assign pediments (sculptural elements) to the temple [SUPPORTED: https://en.wikipedia.org/wiki/Hekatompedon]; The temple''s pediments were painted [SUPPORTED: https://en.wikipedia.org/wiki/Hekatompedon]; A pediment showed lionesses tearing apart a bull [SUPPORTED: https://en.wikipedia.org/wiki/Hekatompedon]; A pediment showed Herakles fighting Triton [SUPPORTED: https://en.wikipedia.org/wiki/Hekatompedon]"}]'::jsonb),
    ('b1a2bdd2-590d-4a2f-8168-d398739c1661'::uuid, 'card_description', 'Atop the nexus of three mountain valleys, more than 3,200 meters up, Marcahuamachuco rose from around AD 400: massive castillos, circular double-walled structures, multi-storied galleries.', 'A pre-Inca city built from around 400 AD, nicknamed ''Machu Picchu of the North.'' Its circular galleries and monumental stone walls predate Inca construction by centuries.', 'teaser-card-s005-rollback:b1a2bdd2-590d-4a2f-8168-d398739c1661:card_description', 'rollback of teaser-card-s005: card_description "A pre-Inca city built from around 400 AD, nicknamed ''Machu Picchu of the North.'' Its circular galleries and monumental stone walls predate Inca construction by centuries." restored on Marcahuamachuco', '7334133cbde49dd80ff49ca64754d355785a74b5a015d912573e2f5180f2e10d|a1847c6b23697c34458c21088f9ca7f1cfae8ffd3e778180d80ead977d9dac2d|a1847c6b23697c34458c21088f9ca7f1cfae8ffd3e778180d80ead977d9dac2d', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Atop the nexus of three mountain valleys, more than 3,200 meters up, Marcahuamachuco rose from around AD 400: massive castillos, circular double-walled structures, multi-storied galleries."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Marcahuamachuco is set atop the nexus of three mountain valleys [S5]; it is more than 3,200 meters up [S5]; construction began around AD 400 [S2]; it has massive castillos [S6]; it has circular double-walled structures [S6]; it has multi-storied galleries [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Marcahuamachuco is a pre-Inca archaeological site (a monumental complex of ruins) in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Marcahuamachuco]; Marcahuamachuco sits atop the nexus of three mountain valleys [SUPPORTED: https://en.wikipedia.org/wiki/Marcahuamachuco]; The site lies more than 3,200 meters up [SUPPORTED: https://en.wikipedia.org/wiki/Marcahuamachuco]; Marcahuamachuco rose (was built) from around AD 400 [SUPPORTED: https://en.wikipedia.org/wiki/Marcahuamachuco]; The site has massive castillos [SUPPORTED: https://en.wikipedia.org/wiki/Marcahuamachuco]; The site has circular double-walled structures [SUPPORTED: https://en.wikipedia.org/wiki/Marcahuamachuco]; The site has multi-storied galleries [SUPPORTED: https://en.wikipedia.org/wiki/Marcahuamachuco]"}]'::jsonb),
    ('b1eabcf0-cc21-4053-92a1-285b30da510b'::uuid, 'card_description', 'Found in the Gorbea Natural Park on 20 March 2004, the Arlobi Menhir is siliceous sandstone that probably came from Illumbe, and archaeologists have traced where it was originally placed.', 'Standing stone in the Gorbea Natural Park, dragged from the mountain’s southern slopes and erected in the Albian Age. The park’s most visited attraction, rediscovered in the 20th century.', 'teaser-card-s005-rollback:b1eabcf0-cc21-4053-92a1-285b30da510b:card_description', 'rollback of teaser-card-s005: card_description ''Standing stone in the Gorbea Natural Park, dragged from the mountain’s southern slopes and erected in the Albian Age. The park’s most visited attraction, rediscovered in the 20th century.'' restored on Arlobi Menhir', 'd0bdcc99ea1899cb833826ff5c6582727b37e9286f0953faf51e88b403961ef0|0cb45cf1b413a720f6ac52195b8f224e733bbacba6dbf934572fc534b765d1ff|0cb45cf1b413a720f6ac52195b8f224e733bbacba6dbf934572fc534b765d1ff', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Found in the Gorbea Natural Park on 20 March 2004, the Arlobi Menhir is siliceous sandstone that probably came from Illumbe, and archaeologists have traced where it was originally placed."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the menhir is in the Gorbea Natural Park [S1]; it was found on 20 March 2004 [S2]; it is siliceous sandstone [S3]; the stone probably came from Illumbe [S3]; archaeologists have found where it was originally placed [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Arlobi Menhir is a menhir (standing stone) in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Arlobi_menhir]; The menhir is in the Gorbea Natural Park [SUPPORTED: https://en.wikipedia.org/wiki/Arlobi_menhir]; The menhir was found on 20 March 2004 [SUPPORTED: https://en.wikipedia.org/wiki/Arlobi_menhir]; The menhir is made of siliceous sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Arlobi_menhir]; The stone probably came from Illumbe [SUPPORTED: https://en.wikipedia.org/wiki/Arlobi_menhir]; Archaeologists have traced where the menhir was originally placed [SUPPORTED: https://en.wikipedia.org/wiki/Arlobi_menhir]"}]'::jsonb),
    ('b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3'::uuid, 'card_description', 'On a gentle slope above a dry valley, the Bronze Age enclosure of South Lodge Camp held two round timber buildings and a mound of burnt flint thought to be a cooking area.', 'South Lodge Camp is an archaeological site of the Bronze Age, about 0.6 miles south-east of the village of Tollard Royal, in Wiltshire.', 'teaser-card-s005-rollback:b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3:card_description', 'rollback of teaser-card-s005: card_description ''South Lodge Camp is an archaeological site of the Bronze Age, about 0.6 miles south-east of the village of Tollard Royal, in Wiltshire.'' restored on South Lodge Camp', '6a56da846c4c65984dc9bd4d9389c4f906ce7a2ed57c8035448ded24ddd3f4f3|2be005eb6dcd9ff63fb5482fd15fb720ef4a20cf702ba37e42376fa817e825f3|2be005eb6dcd9ff63fb5482fd15fb720ef4a20cf702ba37e42376fa817e825f3', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a gentle slope above a dry valley, the Bronze Age enclosure of South Lodge Camp held two round timber buildings and a mound of burnt flint thought to be a cooking area."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is on a gentle slope above a dry valley [S2]; South Lodge Camp is a Bronze Age site with an enclosure [S1, S3]; two round timber buildings were found inside the enclosure [S6]; a mound of burnt flint was found inside the enclosure [S6]; the burnt flint mound is thought to be a cooking area [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "South Lodge Camp is a Bronze Age archaeological site in England [SUPPORTED: https://en.wikipedia.org/wiki/South_Lodge_Camp]; South Lodge Camp is an enclosure [SUPPORTED: https://en.wikipedia.org/wiki/South_Lodge_Camp]; The site dates to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/South_Lodge_Camp]; The site lies on a gentle slope above a dry valley [SUPPORTED: https://en.wikipedia.org/wiki/South_Lodge_Camp]; The enclosure held two round timber buildings [SUPPORTED: https://en.wikipedia.org/wiki/South_Lodge_Camp]; The enclosure held a mound of burnt flint thought to be a cooking area [SUPPORTED: https://en.wikipedia.org/wiki/South_Lodge_Camp]"}]'::jsonb),
    ('b2a6a85b-d671-41a5-b939-f22ddf32ee59'::uuid, 'card_description', 'On a chalk spur of the South Downs, the Iron Age hillfort of Torberry Hill held infilled storage pits and yielded a curry comb, two knives, an iron spearhead and a horn weaving-comb.', 'A hillfort occupied in two phases: an early Iron Age ring fort from ~800 BC and a later promontory fort from ~300 BC. Folklore calls the hill a giant''s grave.', 'teaser-card-s005-rollback:b2a6a85b-d671-41a5-b939-f22ddf32ee59:card_description', 'rollback of teaser-card-s005: card_description "A hillfort occupied in two phases: an early Iron Age ring fort from ~800 BC and a later promontory fort from ~300 BC. Folklore calls the hill a giant''s grave." restored on Torberry Hill', 'ceeb72bd5d8f546d07e782a2182aaab229acc8d8d3ad6e368392a5b443d27ec4|dd9bba0a5d38d80423d6bf59ef0de27e21d5fc6e166b628e5834c32543ae7491|dd9bba0a5d38d80423d6bf59ef0de27e21d5fc6e166b628e5834c32543ae7491', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a chalk spur of the South Downs, the Iron Age hillfort of Torberry Hill held infilled storage pits and yielded a curry comb, two knives, an iron spearhead and a horn weaving-comb."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the hillfort is on a chalk spur of the South Downs [S3]; Torberry Hill is an Iron Age hillfort [S1]; its interior held infilled storage pits [S6]; finds include a curry comb, two knives, an iron spearhead and a horn weaving-comb [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Torberry Hill is an Iron Age hillfort in England [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]; Torberry Hill is a chalk spur of the South Downs [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]; The hillfort held infilled storage pits [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]; The site yielded a curry comb [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]; The site yielded two knives [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]; The site yielded an iron spearhead [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]; The site yielded a horn weaving-comb [SUPPORTED: https://en.wikipedia.org/wiki/Torberry_Hill]"}]'::jsonb),
    ('b36ba7d0-962c-48cc-93c2-717890bb64e7'::uuid, 'card_description', 'On the bed of a now-defunct river in the Flag Fen basin, a sudden, catastrophic fire destroyed the Must Farm Bronze Age Settlement, and oxygen-depleted silts kept it exceptionally preserved.', 'Bronze Age stilt houses that collapsed into a river after a catastrophic fire, preserving everything inside. Textiles, tools, and even food bowls with meals still in them survived intact.', 'teaser-card-s005-rollback:b36ba7d0-962c-48cc-93c2-717890bb64e7:card_description', 'rollback of teaser-card-s005: card_description ''Bronze Age stilt houses that collapsed into a river after a catastrophic fire, preserving everything inside. Textiles, tools, and even food bowls with meals still in them survived intact.'' restored on Must Farm Bronze Age Settlement', 'fab4cd32585b0a829f19d96ded3b685ada38c1d6311eff58b04bd25d99c052c6|912d9b5b6ed435f699620b8bb97cce10cd4a8d333cc2772e76943be02bc2f4e0|912d9b5b6ed435f699620b8bb97cce10cd4a8d333cc2772e76943be02bc2f4e0', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the bed of a now-defunct river in the Flag Fen basin, a sudden, catastrophic fire destroyed the Must Farm Bronze Age Settlement, and oxygen-depleted silts kept it exceptionally preserved."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site lies on the bed of a now-defunct river [S3]; the river bed is in the Flag Fen basin [S3]; the settlement dates to the Bronze Age [S1]; the settlement was destroyed by a sudden, catastrophic fire [S2]; oxygen-depleted river silts contributed to its exceptional preservation [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Must Farm is a Bronze Age settlement (houses raised on stilts above a river) in England [SUPPORTED: https://en.wikipedia.org/wiki/Must_Farm]; The site lies on the bed of a now-defunct river [SUPPORTED: https://en.wikipedia.org/wiki/Must_Farm]; The site is in the Flag Fen basin [SUPPORTED: https://en.wikipedia.org/wiki/Must_Farm]; The settlement was destroyed suddenly by a catastrophic fire [SUPPORTED: https://en.wikipedia.org/wiki/Must_Farm]; Oxygen-depleted (river) silts preserved the settlement [SUPPORTED: https://en.wikipedia.org/wiki/Must_Farm]; The settlement is exceptionally well preserved [SUPPORTED: https://en.wikipedia.org/wiki/Must_Farm]"}]'::jsonb),
    ('b394e9cc-950d-45f6-9506-947b61692668'::uuid, 'card_description', 'A minor ridge road cuts through Milber Down, an Iron Age hill fort about 110 metres above sea level over Newton Abbot in Devon. One artefact found there was a figurine of a stag.', 'Bisected by a minor road near Newton Abbot, Milber Down''s fort sits 110 metres above sea level. A rare bronze stag figurine found here hints at ritual activity beyond military use.', 'teaser-card-s005-rollback:b394e9cc-950d-45f6-9506-947b61692668:card_description', 'rollback of teaser-card-s005: card_description "Bisected by a minor road near Newton Abbot, Milber Down''s fort sits 110 metres above sea level. A rare bronze stag figurine found here hints at ritual activity beyond military use." restored on Milber Down', 'cdc3a919e5cdb8534e790b591113d978941d4374de7df8bf2dfca037b5d48484|44471fdef120f75f5d09ff135aca29a45144823fa3d244cbe9ea10a4ea405316|44471fdef120f75f5d09ff135aca29a45144823fa3d244cbe9ea10a4ea405316', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "A minor ridge road cuts through Milber Down, an Iron Age hill fort about 110 metres above sea level over Newton Abbot in Devon. One artefact found there was a figurine of a stag."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "a minor ridge road cuts through the fort [S2]; Milber Down is an Iron Age hill fort [S1]; the fort lies about 110 metres above sea level [S2]; it stands on a hill above Newton Abbot [S1]; it is in Devon [S1]; one artefact found there was a figurine of a stag [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Milber Down is an Iron Age hill fort. [SUPPORTED: https://www.devon.gov.uk/historicenvironment/schools-resources/milber-down-iron-age-hillfort-newton-abbot-teignbridge-devon/]; Milber Down lies on a hill above Newton Abbot. [SUPPORTED: https://en.wikipedia.org/wiki/Milber_Down]; Milber Down is in Devon. [SUPPORTED: https://en.wikipedia.org/wiki/Milber_Down]; The hill fort is about 110 metres above sea level. [SUPPORTED: https://en.wikipedia.org/wiki/Milber_Down]; A minor ridge road cuts through the hill fort. [SUPPORTED: https://en.wikipedia.org/wiki/Milber_Down]; One artefact found at Milber Down was a figurine of a stag. [SUPPORTED: https://en.wikipedia.org/wiki/Milber_Down]"}]'::jsonb),
    ('b3a11168-712b-445a-b453-c945be7900f3'::uuid, 'card_description', 'On a limestone plateau in the Peak District, about 50 large limestone blocks form the egg-shaped circle of Arbor Low, a Neolithic henge where human bones were found near its central cove.', 'The bank and ditch of the henge, as well as its two entrances, were probably established in the Late Neolithic period, with the stones added later, sometime before 2000 BCE.', 'teaser-card-s005-rollback:b3a11168-712b-445a-b453-c945be7900f3:card_description', 'rollback of teaser-card-s005: card_description ''The bank and ditch of the henge, as well as its two entrances, were probably established in the Late Neolithic period, with the stones added later, sometime before 2000 BCE.'' restored on Arbor Low', 'eeb09ab0a119defd235b8c48a898819fe1fa9ff3b8f624f52182e910f99d94fd|fd0a79f8ceb6e71c5f1b32ed8fdcaeb44a13c8ffeec797b7d498ad30add22ba0|fd0a79f8ceb6e71c5f1b32ed8fdcaeb44a13c8ffeec797b7d498ad30add22ba0', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a limestone plateau in the Peak District, about 50 large limestone blocks form the egg-shaped circle of Arbor Low, a Neolithic henge where human bones were found near its central cove."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site lies on a limestone plateau [S2]; it is in the Peak District [S1]; about 50 large limestone blocks form the circle [S4]; the circle is egg-shaped [S4]; Arbor Low is a Neolithic henge [S1]; the henge has a cove at its centre [S5]; human bones were found near the cove [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Arbor Low is a Neolithic henge. [SUPPORTED: https://en.wikipedia.org/wiki/Arbor_Low]; Arbor Low is in the Peak District. [SUPPORTED: https://en.wikipedia.org/wiki/Arbor_Low]; Arbor Low lies on a limestone plateau. [SUPPORTED: https://en.wikipedia.org/wiki/Arbor_Low]; The circle is formed of about 50 blocks. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/arbor-low-stone-circle-and-gib-hill-barrow/history/]; The blocks are large and of limestone. [SUPPORTED: https://en.wikipedia.org/wiki/Arbor_Low]; The blocks form an egg-shaped circle. [SUPPORTED: https://en.wikipedia.org/wiki/Arbor_Low]; Arbor Low has a cove at its centre. [SUPPORTED: https://en.wikipedia.org/wiki/Arbor_Low]; Human bones were found near the cove. [SUPPORTED: https://en.wikipedia.org/wiki/Arbor_Low]"}]'::jsonb),
    ('b539ba9e-5d7e-4ce8-a9ff-943ac3247297'::uuid, 'card_description', 'Near the south coast of Brittany, the Carnac Stones crowd the land: granite alignments, dolmens, menhirs and great burial mounds holding axeheads, many of jade from the Italian Alps.', 'Over 3,000 standing stones hewn from local granite -- the largest such collection in the world. Erected by pre-Celtic people, their purpose remains one of archaeology''s mysteries.', 'teaser-card-s005-rollback:b539ba9e-5d7e-4ce8-a9ff-943ac3247297:card_description', 'rollback of teaser-card-s005: card_description "Over 3,000 standing stones hewn from local granite -- the largest such collection in the world. Erected by pre-Celtic people, their purpose remains one of archaeology''s mysteries." restored on Carnac Stones', 'cac39f47e4cc327c941134cab332ab78a45fb6a6702156a43c7229ba3bf1a7e0|eca0e1ac1b199ad1e6f5cacf7ed80bbec31ff82faa2cf906f33ea1f3cf11786a|eca0e1ac1b199ad1e6f5cacf7ed80bbec31ff82faa2cf906f33ea1f3cf11786a', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Near the south coast of Brittany, the Carnac Stones crowd the land: granite alignments, dolmens, menhirs and great burial mounds holding axeheads, many of jade from the Italian Alps."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Carnac Stones are near the south coast of Brittany [S1]; the Carnac Stones are a dense collection crowding the land [S1]; they include alignments of standing stones [S1]; the standing stones are granite [S3]; they include dolmens [S1]; they include menhirs [S1]; they include great burial mounds [S1, S4]; the burial mounds held axeheads [S5]; many of the axeheads are of jade from the Italian Alps [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Carnac Stones are a collection of megalithic sites near the south coast of Brittany. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; The monuments are densely packed (they crowd the land). [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; The site includes stone alignments. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; The stones are of granite. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; The site includes dolmens. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; The site includes menhirs. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; The site includes great (exceptionally large) burial mounds. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; The burial mounds held axeheads. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]; Many of the axeheads are of jade from the Italian Alps. [SUPPORTED: https://en.wikipedia.org/wiki/Carnac_stones]"}]'::jsonb),
    ('b577f36e-74a7-4433-a24f-de51defcfca5'::uuid, 'card_description', 'LiDAR images suggest the people of Uxbenka reshaped the hilltops of Toledo, Belize''s southernmost district, for public and residential structures. Only two of its stelae still stand.', 'Some LiDAR images suggest that the people of Uxbenka utilized and modified the hilltops for public and residential structures.', 'teaser-card-s005-rollback:b577f36e-74a7-4433-a24f-de51defcfca5:card_description', 'rollback of teaser-card-s005: card_description ''Some LiDAR images suggest that the people of Uxbenka utilized and modified the hilltops for public and residential structures.'' restored on Uxbenka', '5740e3ba7b7a3673129422c09ad3b4a7047cb33464cb2f25f21b84713c7750e1|ea4c14b1c150a4230ddf75dd6bdd1f3c1725898482833c469f6e69fe1209d521|ea4c14b1c150a4230ddf75dd6bdd1f3c1725898482833c469f6e69fe1209d521', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "LiDAR images suggest the people of Uxbenka reshaped the hilltops of Toledo, Belize''s southernmost district, for public and residential structures. Only two of its stelae still stand."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "LiDAR images suggest the people of Uxbenka modified the hilltops [S3]; the hilltops were used for public and residential structures [S3]; Uxbenka is in Toledo [S1]; Toledo is Belize''s southernmost district [S1]; only two of Uxbenka''s stelae still stand [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Uxbenka is an ancient (pre-Columbian Maya) settlement, an archaeological site in the Toledo District of Belize [SUPPORTED: https://en.wikipedia.org/wiki/Uxbenka]; Toledo is Belize''s southernmost district [SUPPORTED: https://en.wikipedia.org/wiki/Uxbenka]; LiDAR images suggest the people of Uxbenka modified (reshaped) the hilltops [SUPPORTED: https://en.wikipedia.org/wiki/Uxbenka]; The modified hilltops were used for public and residential structures [SUPPORTED: https://en.wikipedia.org/wiki/Uxbenka]; Uxbenka has stelae [SUPPORTED: https://en.wikipedia.org/wiki/Uxbenka]; Only two of its stelae still stand [SUPPORTED: https://en.wikipedia.org/wiki/Uxbenka]"}]'::jsonb),
    ('b5af43a8-181e-47d2-8a3c-0bfdbd445b5e'::uuid, 'card_description', 'Where Hadrian''s Wall crosses the Knag Burn, east of Housesteads, one lane ran between guard-chambers with a gate at each end: the Knag Burn Gateway, a two-stage passage through the wall.', 'A 4th-century gateway added through Hadrian''s Wall where a burn flows beneath via a culvert. One of the rare later additions that pierced the wall.', 'teaser-card-s005-rollback:b5af43a8-181e-47d2-8a3c-0bfdbd445b5e:card_description', 'rollback of teaser-card-s005: card_description "A 4th-century gateway added through Hadrian''s Wall where a burn flows beneath via a culvert. One of the rare later additions that pierced the wall." restored on Knag Burn Gateway', '1c1765bfff96e312ef6ec7cfaa721f6c4e48664f0e238e93bdcbcbb562a8a492|7eeb122a8eaab63795ca25caec17804ad5dd5256656afc22fbc9d5f28e7abd99|7eeb122a8eaab63795ca25caec17804ad5dd5256656afc22fbc9d5f28e7abd99', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Where Hadrian''s Wall crosses the Knag Burn, east of Housesteads, one lane ran between guard-chambers with a gate at each end: the Knag Burn Gateway, a two-stage passage through the wall."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the gateway is where Hadrian''s Wall crosses the Knag Burn [S2]; it is east of Housesteads [S2]; it had a single lane [S4]; the lane ran between guard-chambers [S4]; there was a gate at each end [S4]; the site is the Knag Burn Gateway [S1]; it gave two-stage passage through the wall [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Knag Burn Gateway is a gateway through Hadrian''s Wall in England. [SUPPORTED: https://en.wikipedia.org/wiki/Knag_Burn_Gateway]; The gateway stands where Hadrian''s Wall crosses the Knag Burn. [SUPPORTED: https://en.wikipedia.org/wiki/Knag_Burn_Gateway]; The gateway lies east of Housesteads. [SUPPORTED: https://en.wikipedia.org/wiki/Knag_Burn_Gateway]; The gateway had a single lane (one passage). [SUPPORTED: https://en.wikipedia.org/wiki/Knag_Burn_Gateway]; The lane ran between guard-chambers on either side. [SUPPORTED: https://en.wikipedia.org/wiki/Knag_Burn_Gateway]; There was a gate at each end of the passage. [SUPPORTED: https://en.wikipedia.org/wiki/Knag_Burn_Gateway]; The gateway formed a two-stage passage through the wall. [SUPPORTED: https://en.wikipedia.org/wiki/Knag_Burn_Gateway]"}]'::jsonb),
    ('b612f959-939d-44be-852b-86e9b34ee902'::uuid, 'card_description', 'In woodland at the end of a narrow, steep-sided ridge lie the earthworks of Highbury Hill, an Iron Age hillfort in Somerset where Roman silver coins were found in the late 18th century.', 'Hidden in woodland on a narrow ridge, this univallate fort covers 3 hectares with an 8-metre-wide ditch. Roman silver coins found inside suggest use extended well beyond the Iron Age.', 'teaser-card-s005-rollback:b612f959-939d-44be-852b-86e9b34ee902:card_description', 'rollback of teaser-card-s005: card_description ''Hidden in woodland on a narrow ridge, this univallate fort covers 3 hectares with an 8-metre-wide ditch. Roman silver coins found inside suggest use extended well beyond the Iron Age.'' restored on Highbury Hill, Clutton', 'c1e25a13d43e9c91c545b357a3ec0f4be18e889d0ba3d8660898b0a2dc985015|55b7e0438408604f016efe51849905056c5a928abb8b33aca7ed83407e14b3a4|55b7e0438408604f016efe51849905056c5a928abb8b33aca7ed83407e14b3a4', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In woodland at the end of a narrow, steep-sided ridge lie the earthworks of Highbury Hill, an Iron Age hillfort in Somerset where Roman silver coins were found in the late 18th century."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site lies in woodland [S2]; it lies at the end of a narrow ridge [S2]; the ridge has steep slopes [S2]; earthworks remain there [S1]; Highbury Hill is an Iron Age hillfort [S1]; it is in Somerset [S1]; Roman silver coins were found there [S4]; the coins were found in the late 18th century [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Highbury Hill is a hillfort in Somerset (at Clutton). [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; The hillfort dates from the Iron Age. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; Highbury Hill is in Somerset. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; What survives of the hillfort are earthworks. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; The hillfort lies in woodland. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; The hillfort lies at the end of a narrow ridge. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; The ridge is steep-sided. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; Roman silver coins were found at the site. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]; The Roman silver coins were found in the late 18th century. [SUPPORTED: https://en.wikipedia.org/wiki/Highbury_Hill,_Clutton]"}]'::jsonb),
    ('b656d341-6132-4601-a0d3-386e7e725b6f'::uuid, 'card_description', 'Before 500 new houses were built near Wellington, digs in 2013 found the unknown Longforth Farm: stone foundations around courtyards, their decorated floor tiles like Glastonbury Abbey''s.', 'A Bronze Age landscape and Medieval structure uncovered during housing construction in 2013. Decorated tile foundations had lain completely unknown just below the surface.', 'teaser-card-s005-rollback:b656d341-6132-4601-a0d3-386e7e725b6f:card_description', 'rollback of teaser-card-s005: card_description ''A Bronze Age landscape and Medieval structure uncovered during housing construction in 2013. Decorated tile foundations had lain completely unknown just below the surface.'' restored on Longforth Farm', '0b29a6d5934f2f77971bcfead81614fbee6c40826aa150afea619195c50ae028|d3a8bedf8110f46d6f57a85614118d2c7e936ae17bc9c0830fedeef153cf20c3|d3a8bedf8110f46d6f57a85614118d2c7e936ae17bc9c0830fedeef153cf20c3', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Before 500 new houses were built near Wellington, digs in 2013 found the unknown Longforth Farm: stone foundations around courtyards, their decorated floor tiles like Glastonbury Abbey''s."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "500 new houses were to be built [S2]; the site is near Wellington [S1]; excavations took place in 2013, before the houses were built [S2]; the site was previously unknown [S2]; the site is Longforth Farm [S1]; stone foundations were found [S3]; the foundations are laid out around courtyards [S3]; the foundations carry decorated tiles [S3]; the floor tiles are like those at Glastonbury Abbey [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Longforth Farm near Wellington is the site of a complex of buildings whose stone foundations lie around courtyards. [SUPPORTED: https://www.bbc.com/news/uk-england-somerset-23224087]; The site is near Wellington. [SUPPORTED: https://en.wikipedia.org/wiki/Longforth_Farm]; The site was found by digs in 2013. [SUPPORTED: https://en.wikipedia.org/wiki/Longforth_Farm]; The digs took place before new houses were built there. [SUPPORTED: https://www.bbc.com/news/uk-england-somerset-23224087]; The houses to be built numbered 500. [SUPPORTED: https://en.wikipedia.org/wiki/Longforth_Farm]; The site was previously unknown. [SUPPORTED: https://www.bbc.com/news/uk-england-somerset-23224087]; Stone foundations were found. [SUPPORTED: https://www.bbc.com/news/uk-england-somerset-23224087]; The stone foundations are laid out around courtyards. [SUPPORTED: https://en.wikipedia.org/wiki/Longforth_Farm]; Decorated floor tiles were found. [SUPPORTED: https://www.bbc.com/news/uk-england-somerset-23224087]; The floor tiles are like those of Glastonbury Abbey. [SUPPORTED: https://en.wikipedia.org/wiki/Longforth_Farm]"}]'::jsonb),
    ('b777562e-098d-4091-988f-79fe2b58db6c'::uuid, 'card_description', 'Hidden under heather on Askwith Moor most of the year, Snowden Crags keeps a stone circle and a cluster of cairns, rediscovered in 2010 with a robber trench of unknown date at its centre.', 'A Neolithic stone circle from around 4300 BC, hidden under dense heather for decades. A robber trench of unknown date cuts through its center.', 'teaser-card-s005-rollback:b777562e-098d-4091-988f-79fe2b58db6c:card_description', 'rollback of teaser-card-s005: card_description ''A Neolithic stone circle from around 4300 BC, hidden under dense heather for decades. A robber trench of unknown date cuts through its center.'' restored on Snowden Crags', '8ed180e758b775955dd6bdb34618fdc71849f0911700f8a3f08237dcbec12d7b|38b8c6e92569797c7bd73433c88f5c992e06fb4cdc9e106cfccbfab20bf1879c|38b8c6e92569797c7bd73433c88f5c992e06fb4cdc9e106cfccbfab20bf1879c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Hidden under heather on Askwith Moor most of the year, Snowden Crags keeps a stone circle and a cluster of cairns, rediscovered in 2010 with a robber trench of unknown date at its centre."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "heather covers the site most of the year, keeping it hidden [S2]; Snowden Crags is on Askwith Moor [S1]; it has a stone circle [S2]; it has a cluster of cairns [S2]; it was rediscovered in 2010 [S3]; there is a robber trench at its centre [S3]; the robber trench is of unknown date [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Snowden Crags is a prehistoric site with a stone circle on Askwith Moor, England. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]; The site lies on Askwith Moor. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]; The site has a stone circle. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]; The site has a cluster of cairns. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]; Heather hides the site for most of the year. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]; The site was rediscovered in 2010. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]; A robber trench lies at the centre of the stone circle. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]; The date of the robber trench is unknown. [SUPPORTED: https://en.wikipedia.org/wiki/Snowden_Crags]"}]'::jsonb),
    ('b8bf4ddf-8b56-4544-adde-843e7577320f'::uuid, 'card_description', 'On the islet of Pseira off Crete, cliffside stairs climb from the harbour to a Minoan town of some 60 buildings ranged round an open square, violently destroyed circa 1550–1450 BC.', 'A Minoan and Mycenaean island port from the 4th to 2nd millennium BC, with about 60 buildings ranged around its harbor. Cliffside stairs once connected the town to its wharf.', 'teaser-card-s005-rollback:b8bf4ddf-8b56-4544-adde-843e7577320f:card_description', 'rollback of teaser-card-s005: card_description ''A Minoan and Mycenaean island port from the 4th to 2nd millennium BC, with about 60 buildings ranged around its harbor. Cliffside stairs once connected the town to its wharf.'' restored on Pseira', 'c72495e92f4138ea0608b516d5fa79ecc2e008301eb889e7e9dd0e75c238e412|bbdcd91c19d5aa02c4d85f6175c97fbbe870cbfa95cc6f3596897447ed635ea7|bbdcd91c19d5aa02c4d85f6175c97fbbe870cbfa95cc6f3596897447ed635ea7', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the islet of Pseira off Crete, cliffside stairs climb from the harbour to a Minoan town of some 60 buildings ranged round an open square, violently destroyed circa 1550–1450 BC."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Pseira is an islet [S1]; it lies off Crete [S1]; cliffside stairs connect the harbour and the town above it [S3]; the town was Minoan [S1, S3]; the town had some 60 buildings [S4]; the buildings were ranged round an open square [S4]; the town was violently destroyed [S5]; the destruction dates to circa 1550-1450 BC [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Pseira is a Minoan town on the islet of Pseira off Crete. [SUPPORTED: https://en.wikipedia.org/wiki/Pseira]; Pseira is an islet off the coast of Crete. [SUPPORTED: http://www.minoancrete.com/pseira.htm]; The town had a harbour. [SUPPORTED: https://en.wikipedia.org/wiki/Pseira]; Cliffside stairs connect the harbour with the town. [SUPPORTED: https://en.wikipedia.org/wiki/Pseira]; The stairs climb up from the harbour to the town. [SUPPORTED: http://www.minoancrete.com/pseira.htm]; The town was Minoan. [SUPPORTED: https://instapstudycenter.net/archaeological-projects/ascsa-projects/pseira/]; The town had some 60 buildings. [SUPPORTED: https://en.wikipedia.org/wiki/Pseira]; The buildings were ranged round an open square. [SUPPORTED: https://en.wikipedia.org/wiki/Pseira]; The town was violently destroyed. [SUPPORTED: https://instapstudycenter.net/archaeological-projects/ascsa-projects/pseira/]; The destruction dates to circa 1550–1450 BC. [SUPPORTED: https://en.wikipedia.org/wiki/Pseira]"}]'::jsonb),
    ('b8f4c5f4-c567-4605-9f3d-9475d2db6362'::uuid, 'card_description', NULL, 'A burial site where a rectangular stone coffin was found during Japanese-era rule. Giant stone piles and artifacts date to the 2nd millennium BC.', 'teaser-card-s005-rollback:b8f4c5f4-c567-4605-9f3d-9475d2db6362:card_description', 'rollback of teaser-card-s005: card_description ''A burial site where a rectangular stone coffin was found during Japanese-era rule. Giant stone piles and artifacts date to the 2nd millennium BC.'' restored on Dulan Site', '||fddeeb9ee4134ed1517660440e5c97f4c77b6334de12b0a183cad4b84cc6f9a4', '[{"source": "lane WB run wb-ws-2026-09-27-03: failed-after-verify-rewrite", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The web check could not prove: A stone coffin was dug up at the site.; The web check could not prove: After the coffin, a giant stone pile was discovered at the site.; The web check could not prove: The site has a coffin area.; The web check could not prove: The site dates back 3,000 years.; The tone rules are broken (see the checker''s reasons).; Rule 1: the card is not evocative or a little mysterious; it reads as an administrative record (township, county, zoning into two areas, heritage grade) - rebuild it around an image the sentences give, such as the rectangular stony coffin excavated during Japanese rule (S2), the giant stone pile found by Academia Sinica (S3) or the 3,000-year age (S4)."}]'::jsonb),
    ('b987ab73-469a-4c3a-9c38-bfe90d05db82'::uuid, 'card_description', 'In 1797 labourers found a large floor mosaic at Horkstow Roman Villa, three panels showing Orpheus, classical myths and a chariot race. The villa''s full layout remains undiscovered.', 'Horkstow Roman villa is a Roman villa and scheduled monument in Horkstow, North Lincolnshire.', 'teaser-card-s005-rollback:b987ab73-469a-4c3a-9c38-bfe90d05db82:card_description', 'rollback of teaser-card-s005: card_description ''Horkstow Roman villa is a Roman villa and scheduled monument in Horkstow, North Lincolnshire.'' restored on Horkstow Roman Villa', '4a64b54e4b4c3d5cb28173cd9bdb1551890c62202136e344af4be997fcf0a0ed|b90b75c0d450c327d0a7b90a63af86638cd6c22199ef7613dba184a8a0f3c884|b90b75c0d450c327d0a7b90a63af86638cd6c22199ef7613dba184a8a0f3c884', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In 1797 labourers found a large floor mosaic at Horkstow Roman Villa, three panels showing Orpheus, classical myths and a chariot race. The villa''s full layout remains undiscovered."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "labourers found a large floor mosaic [S2]; the mosaic was found in 1797 [S2]; the site is Horkstow Roman Villa [S1]; the mosaic has three panels [S6]; one panel shows Orpheus [S7]; one panel shows scenes from classical mythology [S7]; one panel shows a chariot race [S7]; the villa''s full layout has not yet been discovered [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Horkstow Roman Villa is a Roman villa in England (Horkstow, North Lincolnshire). [SUPPORTED: https://en.wikipedia.org/wiki/Horkstow_Roman_villa]; The floor mosaic was found in 1797. [SUPPORTED: http://museumcollections.hullcc.gov.uk/collections/storydetail.php?master=691]; Labourers found the mosaic. [SUPPORTED: https://en.wikipedia.org/wiki/Horkstow_Roman_villa]; The mosaic is a large floor mosaic. [SUPPORTED: http://museumcollections.hullcc.gov.uk/collections/storydetail.php?master=691]; The mosaic has three panels. [SUPPORTED: http://museumcollections.hullcc.gov.uk/collections/storydetail.php?master=691]; One panel shows Orpheus. [SUPPORTED: http://museumcollections.hullcc.gov.uk/collections/storydetail.php?master=691]; One panel shows classical myths. [SUPPORTED: http://museumcollections.hullcc.gov.uk/collections/storydetail.php?master=691]; One panel shows a chariot race. [SUPPORTED: http://museumcollections.hullcc.gov.uk/collections/storydetail.php?master=691]; The villa''s full layout remains undiscovered. [SUPPORTED: https://en.wikipedia.org/wiki/Horkstow_Roman_villa]"}]'::jsonb),
    ('ba020c96-afeb-452a-8dbc-faf14155c96c'::uuid, 'card_description', 'Near Benllech on Anglesey, the massive capstone of the Neolithic Pant-y-Saer Burial Chamber rests one end on the ground. Excavations found the remains of fifty-six people buried here.', 'The remains of fifty-six people who were buried here have been found during excavations.', 'teaser-card-s005-rollback:ba020c96-afeb-452a-8dbc-faf14155c96c:card_description', 'rollback of teaser-card-s005: card_description ''The remains of fifty-six people who were buried here have been found during excavations.'' restored on Pant-y-Saer Burial Chamber', 'a6f631c82d9814bd09edbce1d5ca765a811a92def849f2cb3c52cf849eec6641|5d4de326e5a19078763b13728c2581f9c5f1b5d854f06cd17996adfba1a2bf40|5d4de326e5a19078763b13728c2581f9c5f1b5d854f06cd17996adfba1a2bf40', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Near Benllech on Anglesey, the massive capstone of the Neolithic Pant-y-Saer Burial Chamber rests one end on the ground. Excavations found the remains of fifty-six people buried here."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is near Benllech [S1]; it is on Anglesey [S1]; it has a massive capstone [S2]; the burial chamber is Neolithic [S1]; the capstone rests with one end on the ground [S2, S4]; excavations found remains of people buried there [S3]; the remains are of fifty-six people [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Pant-y-Saer Burial Chamber is a Neolithic burial chamber (a dolmen) near Benllech on Anglesey, Wales. [SUPPORTED: https://en.wikipedia.org/wiki/Pant-y-Saer_Burial_Chamber]; The burial chamber lies near Benllech. [SUPPORTED: https://www.anglesey-history.co.uk/places/prehistoric-monuments/pant-y-saer/]; The burial chamber is on Anglesey. [SUPPORTED: https://en.wikipedia.org/wiki/Pant-y-Saer_Burial_Chamber]; The burial chamber is Neolithic. [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=3244]; The capstone is massive. [SUPPORTED: https://archwilio.org.uk/her/chi3/report/page.php?watprn=GAT3601]; The capstone rests one end on the ground. [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=3244]; Excavations found human remains of people buried here. [SUPPORTED: https://www.anglesey-history.co.uk/places/prehistoric-monuments/pant-y-saer/]; The remains of fifty-six people were found. [SUPPORTED: https://en.wikipedia.org/wiki/Pant-y-Saer_Burial_Chamber]"}]'::jsonb),
    ('ba633252-4119-4f23-b1b7-6bfb3f86f2fc'::uuid, 'card_description', 'Inside a large mound on Orkney, stone steps turn back on themselves and descend to the Iron Age chamber of Mine Howe, 6 meters deep: only about 1.3 metres across, with a corbelled roof.', 'An underground chamber dug 6 metres into a large mound around 2,000 years ago. Narrow steps spiral down into a rock-cut space whose purpose — ritual, storage, or something else — remains unknown.', 'teaser-card-s005-rollback:ba633252-4119-4f23-b1b7-6bfb3f86f2fc:card_description', 'rollback of teaser-card-s005: card_description ''An underground chamber dug 6 metres into a large mound around 2,000 years ago. Narrow steps spiral down into a rock-cut space whose purpose — ritual, storage, or something else — remains unknown.'' restored on Mine Howe', '90e2ed9efd08e33c62f0ed64104479db743bc455d5a7d78c8da576ab9cce18da|32aa9dfabffeb3b4e535e5b82fb4a7cf75e8d826e4d8eddf75f2cc8ba51684f5|32aa9dfabffeb3b4e535e5b82fb4a7cf75e8d826e4d8eddf75f2cc8ba51684f5', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Inside a large mound on Orkney, stone steps turn back on themselves and descend to the Iron Age chamber of Mine Howe, 6 meters deep: only about 1.3 metres across, with a corbelled roof."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the chamber is inside a large mound [S1]; it is on Orkney [S2]; stone steps turn back on themselves [S3]; the steps descend to the chamber [S3]; the chamber is Iron Age [S1]; the chamber is 6 meters deep [S1]; the chamber is only about 1.3 metres across [S4]; the chamber has a corbelled roof [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Mine Howe is an Iron Age underground chamber inside a large mound on Orkney. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]; Mine Howe is on Orkney. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]; The chamber lies inside a large mound. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]; Stone steps descend to the chamber. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]; The steps turn back on themselves on the way down. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]; The chamber is Iron Age. [SUPPORTED: https://www.undiscoveredscotland.co.uk/eastmainland/minehowe/index.html]; The chamber is 6 meters deep. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]; The chamber is only about 1.3 metres across. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]; The chamber has a corbelled roof. [SUPPORTED: https://en.wikipedia.org/wiki/Mine_Howe]"}]'::jsonb),
    ('bab3e7ad-3795-42e6-8a05-b65606e7d708'::uuid, 'card_description', 'Among the rural suburbs of Torres Novas lie the Roman Ruins of Villa Cardillio. In 1932, Jalhay and Afonso do Paço began to investigate its grounds and catalogue what had been built there.', 'Active 1st–4th centuries AD near Torres Novas, this villa takes its name from a mosaic pavement whose inscription remains untranslated. Excavation in 1962 recovered hundreds of coins and bronzes.', 'teaser-card-s005-rollback:bab3e7ad-3795-42e6-8a05-b65606e7d708:card_description', 'rollback of teaser-card-s005: card_description ''Active 1st–4th centuries AD near Torres Novas, this villa takes its name from a mosaic pavement whose inscription remains untranslated. Excavation in 1962 recovered hundreds of coins and bronzes.'' restored on Roman Ruins of Villa Cardillio', '100c624f5fd613d892941ef7ddda445d5440e4f70b5803466d37bcf5a6d625d9|ad6c3e4f85ca483baab60c7f51839cc238d3fb211626034a584b71828564dfe8|ad6c3e4f85ca483baab60c7f51839cc238d3fb211626034a584b71828564dfe8', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Among the rural suburbs of Torres Novas lie the Roman Ruins of Villa Cardillio. In 1932, Jalhay and Afonso do Paço began to investigate its grounds and catalogue what had been built there."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site lies in the rural suburbs of Torres Novas [S3]; the site is Roman ruins, the Roman Ruins of Villa Cardillio [S1]; investigation began in 1932 [S2]; Jalhay and Afonso do Paço began investigating the grounds [S2]; they catalogued the built-up environment [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Roman Ruins of Villa Cardillio are the remains of a Roman villa in the municipality of Torres Novas, Portugal. [SUPPORTED: https://pt.wikipedia.org/wiki/Vila_de_Card%C3%ADlio]; The ruins lie among the rural suburbs of Torres Novas. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Villa_Cardillio]; The investigation of the site began in 1932. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Villa_Cardillio]; Jalhay was one of those who began investigating the site in 1932. [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=47573]; Afonso do Paço began investigating the site together with Jalhay in 1932. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Villa_Cardillio]; They investigated the grounds of the site. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Villa_Cardillio]; They catalogued what had been built there. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Villa_Cardillio]"}]'::jsonb),
    ('bad314d6-47c3-457f-ab77-9600fe9b04d2'::uuid, 'card_description', 'At ancient Nineveh, the Library of Ashurbanipal held more than 30,000 clay tablets and fragments from the 7th century BCE, texts of all kinds, among them the famous Epic of Gilgamesh.', 'Over 30,000 clay tablets assembled by Assyria''s last great king in the 7th century BC. This collection preserved the Epic of Gilgamesh — the oldest known work of literature.', 'teaser-card-s005-rollback:bad314d6-47c3-457f-ab77-9600fe9b04d2:card_description', 'rollback of teaser-card-s005: card_description "Over 30,000 clay tablets assembled by Assyria''s last great king in the 7th century BC. This collection preserved the Epic of Gilgamesh — the oldest known work of literature." restored on Library of Ashurbanipal', 'e7cf0c82db0939d079a173decfa45a362235e52f83889d5ed5f8fe55c347e56b|5d8679b4d52ba3846d54171fe4a6a4a9300d7c99bc2128023c1235bd84b082ab|5d8679b4d52ba3846d54171fe4a6a4a9300d7c99bc2128023c1235bd84b082ab', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At ancient Nineveh, the Library of Ashurbanipal held more than 30,000 clay tablets and fragments from the 7th century BCE, texts of all kinds, among them the famous Epic of Gilgamesh."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Library of Ashurbanipal is at ancient Nineveh [S4]; it held more than 30,000 clay tablets and fragments [S1]; the tablets date from the 7th century BCE [S1]; the tablets contain texts of all kinds [S1]; among its holdings was the famous Epic of Gilgamesh [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Library of Ashurbanipal is a royal library, a collection of clay tablets, found at ancient Nineveh [SUPPORTED: https://en.wikipedia.org/wiki/Library_of_Ashurbanipal]; The library held more than 30,000 clay tablets and fragments [SUPPORTED: https://en.wikipedia.org/wiki/Library_of_Ashurbanipal]; The tablets date from the 7th century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Library_of_Ashurbanipal]; The tablets contain texts of all kinds [SUPPORTED: https://en.wikipedia.org/wiki/Library_of_Ashurbanipal]; Among the library''s texts was the famous Epic of Gilgamesh [SUPPORTED: https://en.wikipedia.org/wiki/Library_of_Ashurbanipal]"}]'::jsonb),
    ('bb9dc8f4-100f-4159-99e6-e44c79bc8e57'::uuid, 'card_description', 'Just northwest of the village of Axeitos, on the Barbanza Peninsula by the estuary of the Ría de Arousa, stands the Dolmen de Axeitos, a prehistoric megalithic dolmen dated to 3600-4000 BC.', 'Eight granite slabs form a polygonal chamber capped by a 4.5 x 3.5 m slab. One of the oldest and largest dolmens in Galicia, it still retains two stones of the original entrance corridor.', 'teaser-card-s005-rollback:bb9dc8f4-100f-4159-99e6-e44c79bc8e57:card_description', 'rollback of teaser-card-s005: card_description ''Eight granite slabs form a polygonal chamber capped by a 4.5 x 3.5 m slab. One of the oldest and largest dolmens in Galicia, it still retains two stones of the original entrance corridor.'' restored on Dolmen de Axeitos', 'a7ce8553e0f51ff0fd0c32595bb1d5c62119d95d6d97c0d70d3ecbbc2eecb7ff|a31178543f8d668469926c2ef85e7d4449b3e4837ebf6b858e2cb098cf4fd0fe|a31178543f8d668469926c2ef85e7d4449b3e4837ebf6b858e2cb098cf4fd0fe', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Just northwest of the village of Axeitos, on the Barbanza Peninsula by the estuary of the Ría de Arousa, stands the Dolmen de Axeitos, a prehistoric megalithic dolmen dated to 3600-4000 BC."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "it stands just northwest of the village of Axeitos [S1]; it is on the Barbanza Peninsula [S1]; it is by the estuary of the Ria de Arousa [S1]; it is a prehistoric megalithic dolmen [S1]; it is dated to 3600-4000 BC [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Dolmen de Axeitos is a megalithic dolmen at the village of Axeitos [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Axeitos]; The dolmen is prehistoric [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Axeitos]; It stands just northwest of the village of Axeitos [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Axeitos]; It is on the Barbanza Peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Axeitos]; It is by the estuary of the Ría de Arousa [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Axeitos]; It is dated to 3600-4000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Axeitos]"}]'::jsonb),
    ('bbb89876-9bbf-47fa-853a-8ca7465f176e'::uuid, 'card_description', 'At Brickell in Miami, excavators found holes cut into the Oolitic limestone bedrock of the Miami Circle, with shell tools and shark teeth that matched artifacts of the historic Tequesta.', 'The Miami Circle, also known as The Miami River Circle, Brickell Point, or The Miami Circle at Brickell Point Site, is an archaeological site in Brickell, Miami, Florida.', 'teaser-card-s005-rollback:bbb89876-9bbf-47fa-853a-8ca7465f176e:card_description', 'rollback of teaser-card-s005: card_description ''The Miami Circle, also known as The Miami River Circle, Brickell Point, or The Miami Circle at Brickell Point Site, is an archaeological site in Brickell, Miami, Florida.'' restored on Miami Circle', 'bf007c4fe8c3fe938c1ebd41603de73782f18c50879bfe4f054482563cbc13a9|00a73469b3616aa0f19fca3ba191bc55635b8e39c6a454aeb93524a286f790ad|00a73469b3616aa0f19fca3ba191bc55635b8e39c6a454aeb93524a286f790ad', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At Brickell in Miami, excavators found holes cut into the Oolitic limestone bedrock of the Miami Circle, with shell tools and shark teeth that matched artifacts of the historic Tequesta."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Miami Circle is at Brickell in Miami [S1]; excavators worked at the site [S4]; they found holes cut into the Oolitic limestone bedrock [S5]; shell tools and shark teeth were found at the site [S6]; these artifacts matched artifacts of the historic Tequesta [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Miami Circle is an archaeological site at Brickell in Miami [SUPPORTED: https://en.wikipedia.org/wiki/Miami_Circle]; Excavators found holes cut into the bedrock at the site [SUPPORTED: https://en.wikipedia.org/wiki/Miami_Circle]; The bedrock the holes are cut into is Oolitic limestone [SUPPORTED: https://en.wikipedia.org/wiki/Miami_Circle]; Shell tools were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Miami_Circle]; Shark teeth were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Miami_Circle]; The shell tools and shark teeth matched artifacts of the historic Tequesta [SUPPORTED: https://en.wikipedia.org/wiki/Miami_Circle]"}]'::jsonb),
    ('bbde3c09-ac95-4fe7-b9d9-1be1fd6452fb'::uuid, 'card_description', 'Glevum began as a Roman fort and in AD 97 became a colonia of retired legionaries, a city within the fortress ramparts, with a basilica, a forum market-place and homes with mosaic floors.', 'A Roman fort from 48 AD at a key Severn crossing, it became a colonia for retired legionaries in 97 AD. It grew into Gloucester — the name derived from the settlement''s Latin title.', 'teaser-card-s005-rollback:bbde3c09-ac95-4fe7-b9d9-1be1fd6452fb:card_description', 'rollback of teaser-card-s005: card_description "A Roman fort from 48 AD at a key Severn crossing, it became a colonia for retired legionaries in 97 AD. It grew into Gloucester — the name derived from the settlement''s Latin title." restored on Glevum', '7102b5c05204e29098f946016ba405562aab552f48c7636f9fa91a2e836257b5|146e8b3801cdb0e0ad80c539a1e2733ce683dfdb4fde60d0334f315ff1498806|146e8b3801cdb0e0ad80c539a1e2733ce683dfdb4fde60d0334f315ff1498806', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Glevum began as a Roman fort and in AD 97 became a colonia of retired legionaries, a city within the fortress ramparts, with a basilica, a forum market-place and homes with mosaic floors."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Glevum began as a Roman fort [S1]; in AD 97 it became a colonia of retired legionaries [S1, S3]; the city was built within the fortress and its ramparts [S5]; it had a basilica [S6]; it had a forum market-place [S6]; it had homes with mosaic floors [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Glevum was a Roman settlement that began as a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Glevum]; Glevum became a colonia in AD 97 [SUPPORTED: https://en.wikipedia.org/wiki/Glevum]; The colonia was one of retired legionaries [SUPPORTED: https://en.wikipedia.org/wiki/Glevum]; The colonia was a city built within the fortress ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Glevum]; The city had a basilica [SUPPORTED: https://en.wikipedia.org/wiki/Glevum]; The city had a forum market-place [SUPPORTED: https://en.wikipedia.org/wiki/Glevum]; The city had homes with mosaic floors [SUPPORTED: https://en.wikipedia.org/wiki/Glevum]"}]'::jsonb),
    ('bc879dfc-3a9d-4007-832b-ecf2bd8fbe75'::uuid, 'card_description', 'At Bhairavakona Waterfalls in the Nallamala hills, cave temples carved out of a single rock hold inscriptions and eight different forms of Shiva, a site of the Shaivism tradition.', 'Eight ancient temples carved into a cliff face beneath a 200-metre waterfall sacred to Shiva. The roar of the falls has accompanied worship at this site for nearly two thousand years.', 'teaser-card-s005-rollback:bc879dfc-3a9d-4007-832b-ecf2bd8fbe75:card_description', 'rollback of teaser-card-s005: card_description ''Eight ancient temples carved into a cliff face beneath a 200-metre waterfall sacred to Shiva. The roar of the falls has accompanied worship at this site for nearly two thousand years.'' restored on Bhairavakona Waterfalls', '9bd1cb624b9579c8e1b35530c60e2b02207c25b1d4863718527997eebeda6106|798149eb9084a1465f001123e32a2f5661c6e045bee69fde47978719623cad68|798149eb9084a1465f001123e32a2f5661c6e045bee69fde47978719623cad68', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "At Bhairavakona Waterfalls in the Nallamala hills, cave temples carved out of a single rock hold inscriptions and eight different forms of Shiva, a site of the Shaivism tradition."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Bhairavakona site has rock-cut cave temples [S1]; it is in the Nallamala hills [S2]; the cave temples are carved out of a single rock [S2]; they hold inscriptions [S3]; they hold eight different forms of Shiva [S3]; it is a site of the Shaivism tradition [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Bhairavakona is a site of rock-cut cave temples in the Nallamala hills [SUPPORTED: https://en.wikipedia.org/wiki/Bhairavakona]; The site lies in the Nallamala hills [SUPPORTED: https://en.wikipedia.org/wiki/Bhairavakona]; There are waterfalls at Bhairavakona [SUPPORTED: https://en.wikipedia.org/wiki/Bhairavakona]; The cave temples are carved out of a single rock [SUPPORTED: https://en.wikipedia.org/wiki/Bhairavakona]; The cave temples hold inscriptions [SUPPORTED: https://en.wikipedia.org/wiki/Bhairavakona]; The cave temples hold eight different forms of Shiva [SUPPORTED: https://en.wikipedia.org/wiki/Bhairavakona]; It is a site of the Shaivism tradition [SUPPORTED: https://en.wikipedia.org/wiki/Bhairavakona]"}]'::jsonb),
    ('bc89e53c-a9e6-465e-9cc9-4a6f844b9589'::uuid, 'card_description', 'Late Pleistocene hunters first camped at Lang Rongrien Rock Shelter. Its layers hold charcoal, stone flakes and animal bones, the oldest charcoal dated to around 39,000 years ago.', 'The oldest use for the rock shelter was as a campground for hunters in the late Pleistocene epoch.', 'teaser-card-s005-rollback:bc89e53c-a9e6-465e-9cc9-4a6f844b9589:card_description', 'rollback of teaser-card-s005: card_description ''The oldest use for the rock shelter was as a campground for hunters in the late Pleistocene epoch.'' restored on Lang Rongrien Rock Shelter', 'aa33ff72d381983d7c09ba44f1e95c7559e411df3ad0c3f27d56fbaf4a05f09c|903d9e2a8d2c6b75bb7546aa241bf15b84519c96588efa89ea16ec4088653b79|903d9e2a8d2c6b75bb7546aa241bf15b84519c96588efa89ea16ec4088653b79', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Late Pleistocene hunters first camped at Lang Rongrien Rock Shelter. Its layers hold charcoal, stone flakes and animal bones, the oldest charcoal dated to around 39,000 years ago."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the first use of the rock shelter was as a camp of hunters [S2]; that first use was in the late Pleistocene [S2]; the rock shelter has layers [S3]; its layers hold charcoal, stone flakes and animal bones [S4]; the oldest charcoal is dated to around 39,000 years ago [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Lang Rongrien Rock Shelter is a rock shelter (a prehistoric habitation site) in Thailand [SUPPORTED: https://en.wikipedia.org/wiki/Lang_Rongrien_Rock_Shelter]; Late Pleistocene hunters were the first to camp at the rock shelter (its earliest use was as a hunters'' campground) [SUPPORTED: https://en.wikipedia.org/wiki/Lang_Rongrien_Rock_Shelter]; Its layers hold charcoal [SUPPORTED: https://en.wikipedia.org/wiki/Lang_Rongrien_Rock_Shelter]; Its layers hold stone flakes [SUPPORTED: https://en.wikipedia.org/wiki/Lang_Rongrien_Rock_Shelter]; Its layers hold animal bones [SUPPORTED: https://en.wikipedia.org/wiki/Lang_Rongrien_Rock_Shelter]; The oldest charcoal (from the occupation layers) is radiocarbon dated to around 39,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Lang_Rongrien_Rock_Shelter]"}]'::jsonb),
    ('bcefdb51-0003-46f4-806a-9bfca2b630e1'::uuid, 'card_description', 'Called a stone circle, Glassonby is really a kerbed cairn: kerb stones ring an oval cairn, two marked with concentric rings or spirals. Outside lay burnt bones and an inverted collared urn.', NULL, 'teaser-card-s005-rollback:bcefdb51-0003-46f4-806a-9bfca2b630e1:card_description', 'rollback of teaser-card-s005: card_description None restored on Glassonby', 'cc347fb9f91ea55c6429d08a66c51e5cdbf9e7b2f7ef5f7331072d2dcb1023b8|c23ba6e75cf7dc720bf74e74fb4a638466086d41e727d7d2062a6f9a7b3ccb13|c23ba6e75cf7dc720bf74e74fb4a638466086d41e727d7d2062a6f9a7b3ccb13', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Called a stone circle, Glassonby is really a kerbed cairn: kerb stones ring an oval cairn, two marked with concentric rings or spirals. Outside lay burnt bones and an inverted collared urn."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Glassonby is called a stone circle [S1]; it is really a kerbed cairn [S1]; kerb stones ring an oval cairn [S2]; two of the stones are marked with concentric rings or spirals [S3]; burnt bones were found outside the circle [S5]; an inverted collared urn was found outside the circle [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Glassonby, in England, is really a kerbed cairn [SUPPORTED: https://en.wikipedia.org/wiki/Glassonby]; Glassonby is called a stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Long_Meg_and_Her_Daughters]; Kerb stones ring an oval cairn [SUPPORTED: https://en.wikipedia.org/wiki/Glassonby]; Two of the kerb stones are marked with concentric rings or spirals [SUPPORTED: https://en.wikipedia.org/wiki/Glassonby]; Burnt bones lay outside the circle [SUPPORTED: https://en.wikipedia.org/wiki/Glassonby]; An inverted collared urn lay outside the circle [SUPPORTED: https://en.wikipedia.org/wiki/Glassonby]"}]'::jsonb),
    ('bd536ec2-bdb9-4da0-8489-e6c58fec5921'::uuid, 'card_description', 'In inland Dalmatia, Burnum was a Roman legionary fortress that later became a town. Its remains include a principia, an aqueduct and an amphitheatre estimated to have held 6,000 spectators.', 'Burnum was a Roman Legionary fortress, later converted to a town. Burnum dates from the middle of the reign of Augustus.', 'teaser-card-s005-rollback:bd536ec2-bdb9-4da0-8489-e6c58fec5921:card_description', 'rollback of teaser-card-s005: card_description ''Burnum was a Roman Legionary fortress, later converted to a town. Burnum dates from the middle of the reign of Augustus.'' restored on Burnum', '9e8090cffab715bf090268a928afe61a78efa2a20ad31bac247655c32752cc8a|56f2bdbc522a2cb50a5ea9692fc74450b7cc9a72f62caf7b8e235aaffc4e2bc2|56f2bdbc522a2cb50a5ea9692fc74450b7cc9a72f62caf7b8e235aaffc4e2bc2', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In inland Dalmatia, Burnum was a Roman legionary fortress that later became a town. Its remains include a principia, an aqueduct and an amphitheatre estimated to have held 6,000 spectators."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Burnum is in inland Dalmatia [S2]; it was a Roman legionary fortress [S1]; it later became a town [S1]; its remains include a principia [S3]; its remains include an aqueduct [S3]; its remains include an amphitheatre [S3]; the amphitheatre is estimated to have held 6,000 spectators [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Burnum was a Roman legionary fortress [SUPPORTED: https://en.wikipedia.org/wiki/Burnum]; Burnum lies in inland Dalmatia (Croatia) [SUPPORTED: https://en.wikipedia.org/wiki/Burnum]; The fortress later became a town [SUPPORTED: https://en.wikipedia.org/wiki/Burnum]; Its remains include a principia [SUPPORTED: https://en.wikipedia.org/wiki/Burnum]; Its remains include an aqueduct [SUPPORTED: https://en.wikipedia.org/wiki/Burnum]; Its remains include an amphitheatre [SUPPORTED: https://www.npkrka.hr/en_us/kulturna-bastina/arheologija/amfiteatar-u-burnumu/]; The amphitheatre is estimated to have held 6,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Burnum]"}]'::jsonb),
    ('bda584af-0bbd-4ade-af5d-7b5a349e9f85'::uuid, 'card_description', 'North-east of Thessaloniki, a necropolis at Derveni, part of a cemetery of the ancient city of Lete, gave up valuable artifacts, among them the Derveni papyrus and the Derveni krater.', 'At Derveni an archeological site is located where a necropolis was discovered, part of a cemetery of the ancient city of Lete.', 'teaser-card-s005-rollback:bda584af-0bbd-4ade-af5d-7b5a349e9f85:card_description', 'rollback of teaser-card-s005: card_description ''At Derveni an archeological site is located where a necropolis was discovered, part of a cemetery of the ancient city of Lete.'' restored on Derveni, Thessaloniki', 'a72e345a3a020b87ccfc36edff8cbc83ba11d19fc881d2d08b76445e66234906|c51c21dc09fea6f86cb9c5d847cb21be62b5a18627edc17123d75501f539d153|c51c21dc09fea6f86cb9c5d847cb21be62b5a18627edc17123d75501f539d153', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "North-east of Thessaloniki, a necropolis at Derveni, part of a cemetery of the ancient city of Lete, gave up valuable artifacts, among them the Derveni papyrus and the Derveni krater."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Derveni is north-east of Thessaloniki [S1]; a necropolis is at Derveni [S2]; the necropolis is part of a cemetery of the ancient city of Lete [S2]; valuable artifacts were uncovered there [S3]; among them the Derveni papyrus [S3]; among them the Derveni krater [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Derveni is the site of an ancient necropolis (in Greece) [SUPPORTED: https://en.wikipedia.