    ('cf6f7651-a72a-40c5-b423-459a2225f3d1'::uuid, 'card_description', 'Digging for an underground car park on the east shore of Lake Zurich struck prehistoric pile dwellings beneath Sechseläutenplatz, and work stopped for nine months while they were recorded.', 'In 2009, construction beneath Zürich''s main square uncovered 2nd-millennium BC pile dwellings. The square — site of the annual Sechseläuten festival — overlies this prehistoric lake-edge settlement.', 'teaser-card-s005-rollback:cf6f7651-a72a-40c5-b423-459a2225f3d1:card_description', 'rollback of teaser-card-s005: card_description "In 2009, construction beneath Zürich''s main square uncovered 2nd-millennium BC pile dwellings. The square — site of the annual Sechseläuten festival — overlies this prehistoric lake-edge settlement." restored on Sechseläutenplatz, Zürich', '9f24b12fa83d80f64542bbf5c19bb10ee1efdf739a0f486d7d93ccf7607250ac|c29d4755b6e2cdfc25880867d744752712b1e19990ea2a02ad3358a4e746680c|c29d4755b6e2cdfc25880867d744752712b1e19990ea2a02ad3358a4e746680c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Digging for an underground car park on the east shore of Lake Zurich struck prehistoric pile dwellings beneath Sechseläutenplatz, and work stopped for nine months while they were recorded."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "digging for an underground parking facility uncovered the remains [S2]; the place is on the east shore of Lake Zurich [S1]; the remains are prehistoric pile dwellings [S2]; the remains lie beneath Sechseläutenplatz [S1, S2]; construction was suspended for nine months [S3]; the remains were recorded during the suspension [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Pile dwellings (a lakeshore pile-dwelling settlement) lay beneath Sechseläutenplatz [SUPPORTED: https://www.stadt-zuerich.ch/de/stadtleben/stadtportraet/zuerichs-geschichte/archaeologie/uwad/unterwasser/parkhaus-opera.html]; Sechseläutenplatz is in Zürich [SUPPORTED: https://en.wikipedia.org/wiki/Sechsel%C3%A4utenplatz]; Sechseläutenplatz lies on the east shore of Lake Zurich [SUPPORTED: https://en.wikipedia.org/wiki/Sechsel%C3%A4utenplatz]; The pile dwellings are prehistoric [SUPPORTED: https://www.stadt-zuerich.ch/de/stadtleben/stadtportraet/zuerichs-geschichte/archaeologie/uwad/unterwasser/parkhaus-opera.html]; The pile dwellings were struck while digging for an underground car park [SUPPORTED: https://en.wikipedia.org/wiki/Sechsel%C3%A4utenplatz]; The construction work stopped for nine months [SUPPORTED: https://en.wikipedia.org/wiki/Sechsel%C3%A4utenplatz]; During the stoppage the pile-dwelling remains were archaeologically recorded [SUPPORTED: https://www.stadt-zuerich.ch/de/stadtleben/stadtportraet/zuerichs-geschichte/archaeologie/uwad/unterwasser/parkhaus-opera.html]"}]'::jsonb),
    ('d0b8b206-14b2-4b9d-856a-ee978836c7a8'::uuid, 'card_description', 'In the middle of the east wall of Diocletian''s Palace, the Silver Gate looks towards the Roman town of Epetia, today Stobreč. In late antiquity it was known as the Porta Orientalis.', 'The Porta Orientalis was a secondary gate of Diocletian''s Palace, as it was not the main gate and was located in the middle of the east wall.', 'teaser-card-s005-rollback:d0b8b206-14b2-4b9d-856a-ee978836c7a8:card_description', 'rollback of teaser-card-s005: card_description "The Porta Orientalis was a secondary gate of Diocletian''s Palace, as it was not the main gate and was located in the middle of the east wall." restored on Silver Gate - Diocletian''s Palace', '6ec450f2afb7a7d20f2e89189df37046d3289269bc7a3a5d232c52a2ff42f238|629c70ca83e31f982b62dab252e130c1dd062f93e20e0228116e08ad2edacc8c|629c70ca83e31f982b62dab252e130c1dd062f93e20e0228116e08ad2edacc8c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In the middle of the east wall of Diocletian''s Palace, the Silver Gate looks towards the Roman town of Epetia, today Stobreč. In late antiquity it was known as the Porta Orientalis."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the gate is in the middle of the east wall [S5]; the gate belongs to Diocletian''s Palace [S1, S5]; the Silver Gate faces towards Epetia [S2]; Epetia was a Roman town [S2]; Epetia is today Stobreč [S2]; in late antiquity the gate was known as the Porta Orientalis [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Silver Gate is one of the Roman gates of Diocletian''s Palace (Split) [SUPPORTED: https://en.wikipedia.org/wiki/Silver_Gate_(Diocletian%27s_Palace)]; The Silver Gate is in the east wall of the palace (its eastern entrance) [SUPPORTED: https://hr.wikipedia.org/wiki/Srebrna_vrata_(Split)]; The gate sits in the middle of the east wall [SUPPORTED: https://en.wikipedia.org/wiki/Silver_Gate_(Diocletian%27s_Palace)]; The gate looks towards Epetia [SUPPORTED: https://en.wikipedia.org/wiki/Silver_Gate_(Diocletian%27s_Palace)]; Epetia was a Roman town [SUPPORTED: https://hr.wikipedia.org/wiki/Srebrna_vrata_(Split)]; Epetia is today Stobreč [SUPPORTED: https://en.wikipedia.org/wiki/Silver_Gate_(Diocletian%27s_Palace)]; In late antiquity the gate was known as the Porta Orientalis [SUPPORTED: https://en.wikipedia.org/wiki/Silver_Gate_(Diocletian%27s_Palace)]"}]'::jsonb),
    ('d13b661b-37ac-4ccb-bc4e-83b0bdd1da9c'::uuid, 'card_description', 'Duggleby Howe, one of the largest round barrows in Britain, had a mound 22 feet high at its eastern end. It was first dug in 1798 or 1799, yet no records of that excavation remain.', 'Dating to roughly 3300 BC, this Great Wold Valley barrow is the largest round barrow in Britain — the dominant mound among four known as the Great Barrows of East Yorkshire.', 'teaser-card-s005-rollback:d13b661b-37ac-4ccb-bc4e-83b0bdd1da9c:card_description', 'rollback of teaser-card-s005: card_description ''Dating to roughly 3300 BC, this Great Wold Valley barrow is the largest round barrow in Britain — the dominant mound among four known as the Great Barrows of East Yorkshire.'' restored on Duggleby Howe', 'e78833e8e7a658765de673ba5c77ad9186b4afe262c21e3b07f3973d939aae00|f558fe70376890416929ccbfbf5b83541a1d436c4096da2f1df0c47a0ad26daf|f558fe70376890416929ccbfbf5b83541a1d436c4096da2f1df0c47a0ad26daf', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Duggleby Howe, one of the largest round barrows in Britain, had a mound 22 feet high at its eastern end. It was first dug in 1798 or 1799, yet no records of that excavation remain."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Duggleby Howe is one of the largest round barrows in Britain [S1]; its mound was 22 feet high at the eastern end [S4]; it was first excavated in 1798 or 1799 [S6]; no records of that first excavation remain [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Duggleby Howe is a round barrow (a burial mound) in England [SUPPORTED: https://en.wikipedia.org/wiki/Duggleby_Howe]; Duggleby Howe is one of the largest round barrows in Britain [SUPPORTED: https://en.wikipedia.org/wiki/Duggleby_Howe]; Its mound was 22 feet high at its eastern end [SUPPORTED: https://en.wikipedia.org/wiki/Duggleby_Howe]; The barrow was first dug (excavated) in 1798 or 1799 [SUPPORTED: https://en.wikipedia.org/wiki/Duggleby_Howe]; No records of that first excavation remain [SUPPORTED: https://en.wikipedia.org/wiki/Duggleby_Howe]"}]'::jsonb),
    ('d1877f2c-7bdb-46ee-8368-950eacc0edd5'::uuid, 'card_description', 'On terraces above the sea on Capri''s north side, Palazzo a Mare holds the remains of an imperial palace built by Augustus and modified by Tiberius, once graced by a semicircular nymphaeum.', 'Augustus built this imperial palace on Capri''s north shore, later modified by Tiberius. According to Tacitus, Tiberius maintained twelve villas on the island — this was among them.', 'teaser-card-s005-rollback:d1877f2c-7bdb-46ee-8368-950eacc0edd5:card_description', 'rollback of teaser-card-s005: card_description "Augustus built this imperial palace on Capri''s north shore, later modified by Tiberius. According to Tacitus, Tiberius maintained twelve villas on the island — this was among them." restored on Palazzo a Mare', '23a58ad2e7208cbb1e51df6334cce5dbe252d2e6f0f785573d1b980d663fa2c6|d41407b271ec8629d4201c4a199df4849eb61791f2e3e8a316e3c878a197b9b0|d41407b271ec8629d4201c4a199df4849eb61791f2e3e8a316e3c878a197b9b0', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On terraces above the sea on Capri''s north side, Palazzo a Mare holds the remains of an imperial palace built by Augustus and modified by Tiberius, once graced by a semicircular nymphaeum."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site lies on terraces above the sea [S3]; it is on the north side of Capri [S1]; it contains the remains of an imperial palace [S1]; the palace was built by Augustus [S1]; the palace was modified by Tiberius [S1]; the palace had a semicircular nymphaeum [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Palazzo a Mare is an archaeological site holding the remains of an ancient Roman imperial palace on the island of Capri, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Palazzo_a_Mare]; The site lies on Capri''s north side [SUPPORTED: https://en.wikipedia.org/wiki/Palazzo_a_Mare]; The site lies on terraces above the sea [SUPPORTED: https://en.wikipedia.org/wiki/Palazzo_a_Mare]; The imperial palace was built by Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Palazzo_a_Mare]; The palace was modified by Tiberius [SUPPORTED: https://en.wikipedia.org/wiki/Palazzo_a_Mare]; The palace once had a semicircular nymphaeum [SUPPORTED: https://en.wikipedia.org/wiki/Palazzo_a_Mare]"}]'::jsonb),
    ('d213752b-d8df-4d17-bd75-63538e87b8ab'::uuid, 'card_description', 'Traostalos, a Minoan peak sanctuary in eastern Crete, gave up clay human and animal figurines, ceramic boats, stone altars and, notably, a female figure with a swollen leg.', 'A Minoan peak sanctuary on Crete whose clay figurines include a female figure with a swollen leg — a healing votive — alongside ceramic boats and stone objects unique to this site.', 'teaser-card-s005-rollback:d213752b-d8df-4d17-bd75-63538e87b8ab:card_description', 'rollback of teaser-card-s005: card_description ''A Minoan peak sanctuary on Crete whose clay figurines include a female figure with a swollen leg — a healing votive — alongside ceramic boats and stone objects unique to this site.'' restored on Traostalos', '3fde090c5a27806558041129e7643f470e07e91d116706c09e31d4206acf699e|e7f8e94568a5288d4a67ddd09983286dfb1bc75aafe1cf1a4c9eda0c8573ebe9|e7f8e94568a5288d4a67ddd09983286dfb1bc75aafe1cf1a4c9eda0c8573ebe9', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Traostalos, a Minoan peak sanctuary in eastern Crete, gave up clay human and animal figurines, ceramic boats, stone altars and, notably, a female figure with a swollen leg."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Traostalos is a Minoan peak sanctuary [S1]; it is in eastern Crete [S1]; clay human and animal figurines were found there [S5]; ceramic boats were found there [S6]; stone altars were found there [S6]; notably, a female figure with a swollen leg was found there [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Traostalos is a Minoan peak sanctuary in eastern Crete, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Traostalos]; Clay human figurines were found at Traostalos [SUPPORTED: https://en.wikipedia.org/wiki/Traostalos]; Clay animal figurines were found at Traostalos [SUPPORTED: https://en.wikipedia.org/wiki/Traostalos]; Ceramic boats were found at Traostalos [SUPPORTED: https://en.wikipedia.org/wiki/Traostalos]; Stone altars were found at Traostalos [SUPPORTED: https://en.wikipedia.org/wiki/Traostalos]; Notably, a female figure with a swollen leg was found at Traostalos [SUPPORTED: https://en.wikipedia.org/wiki/Traostalos]"}]'::jsonb),
    ('d35fe3f8-3e3e-4cb5-8008-fb4232a5db9c'::uuid, 'card_description', 'Now in ruins between Sonseca and Mazarambroz, the Alcantarilla Dam was once 20 metres high, built to supply Roman Toletum with water. Its Arabic name means conduit; its Latin one is unknown.', 'A 2nd-century BC Roman gravity dam, 20 metres high and 550 metres long. It may be the oldest Roman dam ever built, and it supplied the city of Toledo with water.', 'teaser-card-s005-rollback:d35fe3f8-3e3e-4cb5-8008-fb4232a5db9c:card_description', 'rollback of teaser-card-s005: card_description ''A 2nd-century BC Roman gravity dam, 20 metres high and 550 metres long. It may be the oldest Roman dam ever built, and it supplied the city of Toledo with water.'' restored on Alcantarilla Dam', '4e20a95ba1cecb769853c9e20b3ecc40263cfb20eeb72014dcc93bed7ed6b0fa|fb9aecc24c6af08a576844ad6c388485ad5d5b0125795f5410962b18cb09d5cc|fb9aecc24c6af08a576844ad6c388485ad5d5b0125795f5410962b18cb09d5cc', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Now in ruins between Sonseca and Mazarambroz, the Alcantarilla Dam was once 20 metres high, built to supply Roman Toletum with water. Its Arabic name means conduit; its Latin one is unknown."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the dam is now in ruins [S3]; it lies between Sonseca and Mazarambroz [S3]; it was 20 metres high [S6]; it was built to supply water to Toletum [S1]; Toletum was a Roman city [S1]; its name Alcantarilla is of Arabic origin [S5]; Alcantarilla means conduit [S5]; its Latin name is unknown [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Alcantarilla Dam is an ancient Roman dam [SUPPORTED: https://en.wikipedia.org/wiki/Alcantarilla_Dam]; The dam was built to supply Toletum with water [SUPPORTED: https://traianvs.net/textos/presas_in.htm]; Toletum was a Roman city [SUPPORTED: https://en.wikipedia.org/wiki/Alcantarilla_Dam]; The dam is now in ruins [SUPPORTED: https://traianvs.net/textos/presas_in.htm]; The dam lies between Sonseca and Mazarambroz [SUPPORTED: https://en.wikipedia.org/wiki/Alcantarilla_Dam]; The dam was once 20 metres high [SUPPORTED: https://es.wikipedia.org/wiki/Presa_romana_de_Alcantarilla]; The name Alcantarilla is of Arabic origin [SUPPORTED: https://en.wikipedia.org/wiki/Alcantarilla_Dam]; The name Alcantarilla means conduit [SUPPORTED: https://es.wikipedia.org/wiki/Presa_romana_de_Alcantarilla]; The dam''s Latin name is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Alcantarilla_Dam]"}]'::jsonb),
    ('d4ead0d9-4f61-4021-a84d-da1b667f002d'::uuid, 'card_description', 'The Chanka site of K''allapayuq Urqu crowns a mountain of the same name in Peru''s Ayacucho Region, about 3,935 m up, between the communities of Uskhuqucha and Anchiway.', 'Chanka hilltop settlement at 3,935 metres in the Ayacucho highlands. K''allapayuq Urqu occupies a mountain summit in La Mar Province, positioned between two remote Andean communities.', 'teaser-card-s005-rollback:d4ead0d9-4f61-4021-a84d-da1b667f002d:card_description', 'rollback of teaser-card-s005: card_description "Chanka hilltop settlement at 3,935 metres in the Ayacucho highlands. K''allapayuq Urqu occupies a mountain summit in La Mar Province, positioned between two remote Andean communities." restored on K''allapayuq Urqu', '81f336e333a875eb66a86b4f52e6342af686f8c67832e1c38956218740b59113|304e27d48b72a566b4f556000a694cb17a4bc5f7fd232d3959e39f894d34f3fd|304e27d48b72a566b4f556000a694cb17a4bc5f7fd232d3959e39f894d34f3fd', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Chanka site of K''allapayuq Urqu crowns a mountain of the same name in Peru''s Ayacucho Region, about 3,935 m up, between the communities of Uskhuqucha and Anchiway."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "K''allapayuq Urqu is a Chanka site [S2]; it lies on top of a mountain of the same name [S1]; it is in the Ayacucho Region of Peru [S1]; it lies at about 3,935 m [S3]; it lies between the communities of Uskhuqucha and Anchiway [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "K''allapayuq Urqu is an archaeological site on top of (crowning) a mountain of the same name [SUPPORTED: https://en.wikipedia.org/wiki/K%27allapayuq_Urqu]; It is a Chanka site [SUPPORTED: https://en.wikipedia.org/wiki/K%27allapayuq_Urqu]; It lies in Peru''s Ayacucho Region [SUPPORTED: https://en.wikipedia.org/wiki/K%27allapayuq_Urqu]; It lies at about 3,935 m altitude [SUPPORTED: https://en.wikipedia.org/wiki/K%27allapayuq_Urqu]; It lies between the communities of Uskhuqucha and Anchiway [SUPPORTED: https://en.wikipedia.org/wiki/K%27allapayuq_Urqu]"}]'::jsonb),
    ('d4fbbaf4-742a-448f-a424-6f3ddf573c31'::uuid, 'card_description', 'In the north of Roman Toletum, on the outskirts of its walled enclosure, lay the Roman Circus of Toledo, built in the 1st century to serve the city known today as Toledo, Castilla-La Mancha.', 'The Roman circus at Toletum was built in the 1st century, during the reign of emperor Augustus or emperor Tiberius.', 'teaser-card-s005-rollback:d4fbbaf4-742a-448f-a424-6f3ddf573c31:card_description', 'rollback of teaser-card-s005: card_description ''The Roman circus at Toletum was built in the 1st century, during the reign of emperor Augustus or emperor Tiberius.'' restored on Roman Circus of Toledo', '172b621fe846ee5cadcdcc2ab4ee137346ba9673403cea1228998a0c7c149c36|86df91328951e92bc3481409e22abd1d4b9c08b3c29109e9aadb493c1d798a85|86df91328951e92bc3481409e22abd1d4b9c08b3c29109e9aadb493c1d798a85', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In the north of Roman Toletum, on the outskirts of its walled enclosure, lay the Roman Circus of Toledo, built in the 1st century to serve the city known today as Toledo, Castilla-La Mancha."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the circus lay in the north of the Roman city of Toletum [S4]; it lay on the outskirts of the walled enclosure [S5]; it is a Roman circus [S1]; it was built in the 1st century [S3]; it served the city of Toletum [S2]; Toletum is present-day Toledo, Castilla-La Mancha [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Roman Circus of Toledo is a Roman circus (chariot-racing arena) of Roman Toletum [SUPPORTED: https://cultura.castillalamancha.es/patrimonio/catalogo-patrimonio-cultural/circo-romano-de-toledo]; The circus lay in the north of Roman Toletum [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_Toledo]; The circus lay on the outskirts of the city''s walled enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_Toledo]; The circus was built in the 1st century [SUPPORTED: https://cultura.castillalamancha.es/patrimonio/catalogo-patrimonio-cultural/circo-romano-de-toledo]; The circus served the city known today as Toledo [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_Toledo]; Toledo lies in Castilla-La Mancha [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_Toledo]"}]'::jsonb),
    ('d55baca6-8a56-4a3b-8323-f5399e331666'::uuid, 'card_description', 'Flanked by two watch towers, the Eastern Gate of Philippopolis stood on the main road to Byzantium. Rebuilt in the 4th century, it had one wide central entrance and two narrower side ones.', 'A 2nd-century AD gate on the main road to Byzantium, completely rebuilt in the 4th century with twin towers. The gate complex grew into a fortified quarter of its own.', 'teaser-card-s005-rollback:d55baca6-8a56-4a3b-8323-f5399e331666:card_description', 'rollback of teaser-card-s005: card_description ''A 2nd-century AD gate on the main road to Byzantium, completely rebuilt in the 4th century with twin towers. The gate complex grew into a fortified quarter of its own.'' restored on Eastern Gate of Philippopolis', 'a8b5017f0ac403985d540e8aa77d3adb6177ec7784a453350037c9d873bdb119|bc244789ca1d1a400ed81d48ec6ee6383ab83713af67184e989b7f6f17db8a95|bc244789ca1d1a400ed81d48ec6ee6383ab83713af67184e989b7f6f17db8a95', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Flanked by two watch towers, the Eastern Gate of Philippopolis stood on the main road to Byzantium. Rebuilt in the 4th century, it had one wide central entrance and two narrower side ones."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the gate was flanked by two watch towers [S5]; the gate stood on the main road to Byzantium [S2]; the gate was rebuilt in the 4th century [S4]; after the rebuilding it had one wide central entrance [S4]; after the rebuilding it had two narrower side entrances [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Eastern Gate of Philippopolis is a city gate (entrance) of the ancient city of Philippopolis, modern Plovdiv in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis]; It was flanked by two watch towers [SUPPORTED: https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis]; It stood on the main road to Byzantium [SUPPORTED: https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis]; It was rebuilt in the 4th century [SUPPORTED: https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis]; It had one wide central entrance [SUPPORTED: https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis]; It had two narrower side entrances [SUPPORTED: https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis]"}]'::jsonb),
    ('d67b3b53-ac6c-4ed9-9e37-ab42585c1247'::uuid, 'card_description', 'Outside the walls of Arles lies the Alyscamps, a large Roman necropolis where, as early as the 4th century, several thousand tombs forced sarcophagi to be stacked three layers deep.', 'The Alyscamps is a large Roman necropolis, which is a short distance outside the walls of the old town of Arles. The Alyscamps continued to be used after the city was Christianised in the 4th century.', 'teaser-card-s005-rollback:d67b3b53-ac6c-4ed9-9e37-ab42585c1247:card_description', 'rollback of teaser-card-s005: card_description ''The Alyscamps is a large Roman necropolis, which is a short distance outside the walls of the old town of Arles. The Alyscamps continued to be used after the city was Christianised in the 4th century.'' restored on Alyscamps', '5bdf37d126f56f488e8ae72144ae8cd74bac3bb28e19d10304cba72f8ed29553|9061cd2b12d476fd0c362d6b3959a7b5a8f68cb37fae667ca5f6a213c0665807|9061cd2b12d476fd0c362d6b3959a7b5a8f68cb37fae667ca5f6a213c0665807', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Outside the walls of Arles lies the Alyscamps, a large Roman necropolis where, as early as the 4th century, several thousand tombs forced sarcophagi to be stacked three layers deep."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Alyscamps lies outside the walls of Arles [S1]; it is a large Roman necropolis [S1]; as early as the 4th century there were several thousand tombs [S8]; the number of tombs made it necessary to stack sarcophagi three layers deep [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Alyscamps is a large Roman necropolis [SUPPORTED: https://en.wikipedia.org/wiki/Alyscamps]; It lies outside the walls of Arles, France [SUPPORTED: https://en.wikipedia.org/wiki/Alyscamps]; As early as the 4th century it held several thousand tombs [SUPPORTED: https://en.wikipedia.org/wiki/Alyscamps]; The number of tombs forced sarcophagi to be stacked three layers deep [SUPPORTED: https://en.wikipedia.org/wiki/Alyscamps]"}]'::jsonb),
    ('d74c1ef8-f9bc-4feb-8f8f-4aab984e4602'::uuid, 'card_description', 'Near the River Boyne, the Neolithic mound of Dowth still bears the large crater left by a botched excavation in 1847, yet its smaller inner chambers remain largely intact.', 'The third major tomb of Brú na Bóinne alongside Newgrange and Knowth, this passage tomb from around 3200 BC was stripped and left largely as a ruin. Its cairn is 85 meters across and 15 meters high.', 'teaser-card-s005-rollback:d74c1ef8-f9bc-4feb-8f8f-4aab984e4602:card_description', 'rollback of teaser-card-s005: card_description ''The third major tomb of Brú na Bóinne alongside Newgrange and Knowth, this passage tomb from around 3200 BC was stripped and left largely as a ruin. Its cairn is 85 meters across and 15 meters high.'' restored on Dowth', 'aa056eba0641232f962d51ea67220c7c9b58ea790f7a8cd6f43132a059c86ad9|07c603be09e60d36ca11a0c499b8f38d6e0c1c51e8fe1f844909e2074badc9e6|07c603be09e60d36ca11a0c499b8f38d6e0c1c51e8fe1f844909e2074badc9e6', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Near the River Boyne, the Neolithic mound of Dowth still bears the large crater left by a botched excavation in 1847, yet its smaller inner chambers remain largely intact."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Dowth is near the River Boyne [S1]; Dowth is a Neolithic mound (site of Neolithic passage tombs) [S1, S5]; a botched excavation took place in 1847 [S4]; that excavation left a large crater in the mound which is still there [S4]; its smaller inner chambers are largely intact [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Dowth is a Neolithic mound (passage tomb site) near the River Boyne in Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Dowth]; The mound is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Dowth]; It lies near the River Boyne [SUPPORTED: https://en.wikipedia.org/wiki/Dowth]; The mound still bears a large crater [SUPPORTED: https://en.wikipedia.org/wiki/Dowth]; The crater was left by a botched excavation in 1847 [SUPPORTED: https://en.wikipedia.org/wiki/Dowth]; Its smaller inner chambers remain largely intact [SUPPORTED: https://en.wikipedia.org/wiki/Dowth]"}]'::jsonb),
    ('d765c593-eb36-4978-b73f-534333b85bda'::uuid, 'card_description', 'In Lima''s San Miguel District, Huaca Casa Rosada rises as a platform of rammed earth and adobe, approximately 36 meters on each side, that became the base of a Republican-period house.', 'An adobe platform pyramid about 36 metres square, with occupations from the Moche period through the Inca conquest. Built from rammed earth and sun-dried brick.', 'teaser-card-s005-rollback:d765c593-eb36-4978-b73f-534333b85bda:card_description', 'rollback of teaser-card-s005: card_description ''An adobe platform pyramid about 36 metres square, with occupations from the Moche period through the Inca conquest. Built from rammed earth and sun-dried brick.'' restored on Huaca Casa Rosada', '3f80b4103e944fabb73b90f666c63b108b48f46c23fe4ec6105e319668d6e6cd|2e8684d7d032c8edc00014f03a36248a02d5dbace08c4658ccc23a8f2fb3832c|2e8684d7d032c8edc00014f03a36248a02d5dbace08c4658ccc23a8f2fb3832c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In Lima''s San Miguel District, Huaca Casa Rosada rises as a platform of rammed earth and adobe, approximately 36 meters on each side, that became the base of a Republican-period house."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is in San Miguel District, Lima [S1]; it is a platform of rammed earth and adobe [S3]; it measures approximately 36 meters on each side [S3]; it became the base of a Republican-period house [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Huaca Casa Rosada is an archaeological site (a huaca platform) in San Miguel District, Lima, Peru [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Casa_Rosada]; It is a platform built of rammed earth and adobe [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Casa_Rosada]; The platform measures approximately 36 meters on each side [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Casa_Rosada]; The platform became the base of a Republican-period house [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Casa_Rosada]"}]'::jsonb),
    ('d799bb0f-8ffd-4a29-a516-ffd445f6b699'::uuid, 'card_description', 'Found in 2019 near Overstone, the Overstone Anglo-Saxon Cemetery held 154 graves, 3000 artefacts and 22 previously unknown structures, its burials rich in jewellery and weapons.', 'Overstone Anglo-Saxon cemetery is an Anglo-Saxon place of burial discovered at the Overstone Leys housing development site near the village of Overstone, Northamptonshire.', 'teaser-card-s005-rollback:d799bb0f-8ffd-4a29-a516-ffd445f6b699:card_description', 'rollback of teaser-card-s005: card_description ''Overstone Anglo-Saxon cemetery is an Anglo-Saxon place of burial discovered at the Overstone Leys housing development site near the village of Overstone, Northamptonshire.'' restored on Overstone Anglo-Saxon Cemetery', 'd19cb6baac8c56df455eb6aa6f432ee2eb6df3c0aaf9b178bec81f9a318f227b|0dcaf96cee101c4b171a6c747a5f413581f838c3718c165ce48ed466f410e9fa|0dcaf96cee101c4b171a6c747a5f413581f838c3718c165ce48ed466f410e9fa', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Found in 2019 near Overstone, the Overstone Anglo-Saxon Cemetery held 154 graves, 3000 artefacts and 22 previously unknown structures, its burials rich in jewellery and weapons."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the cemetery was found in 2019 [S2]; it lies near Overstone [S1]; it held 154 graves [S5]; 3000 artefacts were found there [S5]; 22 previously unknown structures were found there [S7]; the burials contained many grave goods, mainly jewellery and weapons [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Overstone Anglo-Saxon Cemetery is an Anglo-Saxon cemetery near Overstone, England [SUPPORTED: https://en.wikipedia.org/wiki/Overstone_Anglo-Saxon_cemetery]; The cemetery is near Overstone [SUPPORTED: https://en.wikipedia.org/wiki/Overstone_Anglo-Saxon_cemetery]; It was found in 2019 [SUPPORTED: https://en.wikipedia.org/wiki/Overstone_Anglo-Saxon_cemetery]; It held 154 graves [SUPPORTED: https://en.wikipedia.org/wiki/Overstone_Anglo-Saxon_cemetery]; About 3000 artefacts were found [SUPPORTED, no proving quote: https://www.mola.org.uk/discoveries/news/significant-anglo-saxon-cemetery-and-settlement-found-overstone-northamptonshire]; 22 previously unknown structures were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Overstone_Anglo-Saxon_cemetery]; The burials were rich in jewellery and weapons [SUPPORTED: https://en.wikipedia.org/wiki/Overstone_Anglo-Saxon_cemetery]"}]'::jsonb),
    ('d7a107f8-b228-48a7-97c5-081dc67c0469'::uuid, 'card_description', 'On the east side of the Agora of Athens, the Square Peristyle was begun around 300 BC but never finished. It probably served as law courts; the Stoa of Attalos rose on its foundations.', 'Begun around 300 BC and abandoned unfinished by 275 BC, this large peristyle served briefly as Athens'' law courts before being demolished for material reused in South Stoa II.', 'teaser-card-s005-rollback:d7a107f8-b228-48a7-97c5-081dc67c0469:card_description', 'rollback of teaser-card-s005: card_description "Begun around 300 BC and abandoned unfinished by 275 BC, this large peristyle served briefly as Athens'' law courts before being demolished for material reused in South Stoa II." restored on Square Peristyle', 'a9c3648a91d1174a9d5c0f92f052de95faa9370e35b186aacaa46644b003859c|b5251eba6875f826d9bcf0474b6023a4e7b47e7d275dead3ae238f225c5061af|b5251eba6875f826d9bcf0474b6023a4e7b47e7d275dead3ae238f225c5061af', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the east side of the Agora of Athens, the Square Peristyle was begun around 300 BC but never finished. It probably served as law courts; the Stoa of Attalos rose on its foundations."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Square Peristyle is on the east side of the Agora of Athens [S1]; construction began around 300 BC [S2]; it was never finished [S2]; it probably served as law courts (hedged) [S3]; the Stoa of Attalos was built over its foundations [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Square Peristyle is a building on the east side of the Agora of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Square_Peristyle]; It was begun around 300 BC [SUPPORTED: https://en.wikipedia.org/wiki/Square_Peristyle]; It was never finished [SUPPORTED: https://en.wikipedia.org/wiki/Square_Peristyle]; It probably served as law courts [SUPPORTED: https://en.wikipedia.org/wiki/Square_Peristyle]; The Stoa of Attalos was built on its foundations [SUPPORTED: https://en.wikipedia.org/wiki/Square_Peristyle]"}]'::jsonb),
    ('d849ed4e-d1bc-47f3-9721-247006e54a3c'::uuid, 'card_description', 'In Castile and León, the Roman Arch of Medinaceli stands in stone laid in opus quadratum, a triumphal arch whose central span of 1.90 meters is made of 23 voussoirs.', 'A 1st-century AD triumphal arch at Medinaceli in opus quadratum, built at nearly 1,200 m elevation. Its three barrel vaults are rare — only a handful of triple-arched Roman arches survive anywhere.', 'teaser-card-s005-rollback:d849ed4e-d1bc-47f3-9721-247006e54a3c:card_description', 'rollback of teaser-card-s005: card_description ''A 1st-century AD triumphal arch at Medinaceli in opus quadratum, built at nearly 1,200 m elevation. Its three barrel vaults are rare — only a handful of triple-arched Roman arches survive anywhere.'' restored on Roman Arch of Medinaceli', 'e15ec0e1bda2099173c5fb90017fec04d76d45fb3fb46a75045a54e93f66abd0|02a02bcf211485959c1461dc9d1948e95697b653c646a28009b4f7cef81c5df7|02a02bcf211485959c1461dc9d1948e95697b653c646a28009b4f7cef81c5df7', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In Castile and León, the Roman Arch of Medinaceli stands in stone laid in opus quadratum, a triumphal arch whose central span of 1.90 meters is made of 23 voussoirs."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the arch is in Castile and León [S1]; it is built of stone [S2]; it uses the opus quadratum technique [S2]; it is a triumphal arch [S1]; its central arch has a span of 1.90 meters [S4]; the central arch is made up of 23 voussoirs [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Roman Arch of Medinaceli is a Roman triumphal arch in Medinaceli [SUPPORTED: https://en.wikipedia.org/wiki/Roman_arch_of_Medinaceli]; It is in Castile and Leon [SUPPORTED: https://en.wikipedia.org/wiki/Roman_arch_of_Medinaceli]; The arch still stands [SUPPORTED: https://en.wikipedia.org/wiki/Roman_arch_of_Medinaceli]; It is built of stone [SUPPORTED: https://en.wikipedia.org/wiki/Roman_arch_of_Medinaceli]; The stone is laid in opus quadratum [SUPPORTED: https://en.wikipedia.org/wiki/Roman_arch_of_Medinaceli]; Its central span is 1.90 meters [SUPPORTED: https://en.wikipedia.org/wiki/Roman_arch_of_Medinaceli]; The central arch is made of 23 voussoirs [SUPPORTED: https://es.wikipedia.org/wiki/Arco_de_Medinaceli]"}]'::jsonb),
    ('d9543648-1f50-4614-b33e-398edff7d7d6'::uuid, 'card_description', 'In the Comayagua valley of central Honduras, the Lenca site of Tenampua holds mounds of between 6 and 15 meters, a fortress, a ball court and 250 registered structures.', 'Tenampúa is an archaeological site belonging to the Lenca culture dating from the Mesoamerican classical period.', 'teaser-card-s005-rollback:d9543648-1f50-4614-b33e-398edff7d7d6:card_description', 'rollback of teaser-card-s005: card_description ''Tenampúa is an archaeological site belonging to the Lenca culture dating from the Mesoamerican classical period.'' restored on Tenampua', '171c29c2ad6933d34ae51eb0ac18a225d900dc99ecce7ff0215a16a3713c557c|1e12920dcbfbfa2d7066ecc5f7719b9b5cebf4297b5b98923d164c68dedcc4fc|1e12920dcbfbfa2d7066ecc5f7719b9b5cebf4297b5b98923d164c68dedcc4fc', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In the Comayagua valley of central Honduras, the Lenca site of Tenampua holds mounds of between 6 and 15 meters, a fortress, a ball court and 250 registered structures."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Tenampua is in the Comayagua valley [S1]; it is in central Honduras [S1]; it is a Lenca site [S1]; it has mounds of between 6 and 15 meters [S2]; it has a fortress [S2]; it has a ball court [S3]; 250 structures have been registered there [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Tenampua is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]; It lies in central Honduras [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]; It lies in the Comayagua valley [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]; It is a Lenca site [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]; It holds mounds of between 6 and 15 meters [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]; It holds a fortress [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]; It holds a ball court [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]; 250 structures have been registered at the site [SUPPORTED: https://en.wikipedia.org/wiki/Tenamp%C3%BAa]"}]'::jsonb),
    ('d966ae3d-201a-4028-89f2-50e5df35ae00'::uuid, 'card_description', 'On the eastern slopes of Brown Mountain, Kilmogue Portal Tomb rests a large capstone of quartz-veined granite on two portal stones, its entrance facing the summer solstice sunrise.', 'A portal tomb with a massive granite capstone on two portal stones, aligned toward the summer solstice sunrise. A rare door-stone blocks the entrance.', 'teaser-card-s005-rollback:d966ae3d-201a-4028-89f2-50e5df35ae00:card_description', 'rollback of teaser-card-s005: card_description ''A portal tomb with a massive granite capstone on two portal stones, aligned toward the summer solstice sunrise. A rare door-stone blocks the entrance.'' restored on Kilmogue Portal Tomb', 'ea9a107a8f966c0e00338ce2389e3f6a1cd2701c44cbed46ec70e2851f23f9dc|12fdd27227f8b20bf805c36a2bb702954546a6deae6302cf5527e5f7cf7e9b1c|12fdd27227f8b20bf805c36a2bb702954546a6deae6302cf5527e5f7cf7e9b1c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On the eastern slopes of Brown Mountain, Kilmogue Portal Tomb rests a large capstone of quartz-veined granite on two portal stones, its entrance facing the summer solstice sunrise."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Kilmogue Portal Tomb is on the eastern slopes of Brown Mountain [S2]; it has a large capstone [S3]; it is made of granite with quartz veins [S3]; the capstone rests on two portal stones [S3]; its entrance faces the summer solstice sunrise [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Kilmogue Portal Tomb is a portal tomb (dolmen) in Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Kilmogue_Portal_Tomb]; It lies on the eastern slopes of Brown Mountain [SUPPORTED: https://en.wikipedia.org/wiki/Kilmogue_Portal_Tomb]; It has a large capstone [SUPPORTED: https://en.wikipedia.org/wiki/Kilmogue_Portal_Tomb]; The capstone (the tomb''s stone) is quartz-veined granite [SUPPORTED: https://en.wikipedia.org/wiki/Kilmogue_Portal_Tomb]; The capstone rests on two portal stones [SUPPORTED: https://en.wikipedia.org/wiki/Kilmogue_Portal_Tomb]; Its entrance faces the summer solstice sunrise [SUPPORTED: https://en.wikipedia.org/wiki/Kilmogue_Portal_Tomb]"}]'::jsonb),
    ('d99323af-e720-4cdd-9182-c4a73af9c764'::uuid, 'card_description', 'Within a circle of 11 large stones, a passage just 1 m high leads into Corrimony Chambered Cairn, a Bronze Age tomb where a crouched burial lay beneath a floor of flagstones.', 'A Clava cairn near Glen Urquhart from the 3rd millennium BC, opened in 1952 by Professor Stuart Piggott. Just one skeleton and one artifact — a surprisingly sparse burial for a large monument.', 'teaser-card-s005-rollback:d99323af-e720-4cdd-9182-c4a73af9c764:card_description', 'rollback of teaser-card-s005: card_description ''A Clava cairn near Glen Urquhart from the 3rd millennium BC, opened in 1952 by Professor Stuart Piggott. Just one skeleton and one artifact — a surprisingly sparse burial for a large monument.'' restored on Corrimony Chambered Cairn', 'eb1879879071a559b00d84f9bbe61b0af178567e93491584a89be1a563515e3f|3b0aca08c70b05bdfb3d9b88f9ae4baf3f7341850d0543c4e1201b81d3d034bf|3b0aca08c70b05bdfb3d9b88f9ae4baf3f7341850d0543c4e1201b81d3d034bf', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Within a circle of 11 large stones, a passage just 1 m high leads into Corrimony Chambered Cairn, a Bronze Age tomb where a crouched burial lay beneath a floor of flagstones."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the cairn is surrounded by a circle of 11 large stones [S3]; an entrance passage 1 m high leads into the tomb [S4]; Corrimony Chambered Cairn is a Bronze Age tomb [S1]; a crouched burial was found beneath a floor of flagstones [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Corrimony Chambered Cairn is a Bronze Age tomb (burial monument) in Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Corrimony_chambered_cairn]; It lies in Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Corrimony_chambered_cairn]; It stands within a circle of 11 large stones [SUPPORTED: https://en.wikipedia.org/wiki/Corrimony_chambered_cairn]; A passage 1 m high leads into the cairn (to its chamber) [SUPPORTED: https://en.wikipedia.org/wiki/Corrimony_chambered_cairn]; A crouched burial was found in the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Corrimony_chambered_cairn]; The burial lay beneath a floor of flagstones [SUPPORTED: https://en.wikipedia.org/wiki/Corrimony_chambered_cairn]"}]'::jsonb),
    ('d996c0de-78d1-4966-9ace-3f40a9c6ed2d'::uuid, 'card_description', 'Arkadiko Bridge, a Mycenaean corbel arch in Cyclopean style, is one of the oldest crossable arch bridges still in existence, and its layout suggests chariots could cross it.', 'The Arkadiko Bridge is one of four known Mycenaean corbel arch bridges near Arkadiko in Argolis.', 'teaser-card-s005-rollback:d996c0de-78d1-4966-9ace-3f40a9c6ed2d:card_description', 'rollback of teaser-card-s005: card_description ''The Arkadiko Bridge is one of four known Mycenaean corbel arch bridges near Arkadiko in Argolis.'' restored on Arkadiko Bridge', '2cf032a1c4cbe4f458281c32874dc0e16610edbd160225b8d171aaa8d337ba5a|e2398c6f0800d42d35c42f9e2191d15b6ecdede7d2ea9232d0e8c09ff11211eb|e2398c6f0800d42d35c42f9e2191d15b6ecdede7d2ea9232d0e8c09ff11211eb', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Arkadiko Bridge, a Mycenaean corbel arch in Cyclopean style, is one of the oldest crossable arch bridges still in existence, and its layout suggests chariots could cross it."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Arkadiko Bridge is Mycenaean [S1, S3]; it is a corbel arch bridge [S3]; it is built in Cyclopean style [S3]; it is one of the oldest crossable arch bridges still in existence [S2]; its layout suggests chariots could use it [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Arkadiko Bridge is a Mycenaean bridge in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Arkadiko_Bridge]; It is a corbel arch bridge [SUPPORTED: https://en.wikipedia.org/wiki/Arkadiko_Bridge]; It is built in Cyclopean style [SUPPORTED: https://en.wikipedia.org/wiki/Arkadiko_Bridge]; It is one of the oldest crossable arch bridges still in existence [SUPPORTED: https://en.wikipedia.org/wiki/Arkadiko_Bridge]; Its layout suggests chariots could cross it [SUPPORTED: https://en.wikipedia.org/wiki/Arkadiko_Bridge]"}]'::jsonb),
    ('da2f5fea-80b2-4c88-a5d1-738c054512b5'::uuid, 'card_description', 'In 2006 the Balanica caves gave up half a hominin jaw, the first hominin specimen in the Central Balkans recovered through controlled excavations with firm stratigraphic context.', 'Remains in Velika Balanica make it one of the oldest localities in Europe where transition from the Lower to Middle Paleolithic is recorded.', 'teaser-card-s005-rollback:da2f5fea-80b2-4c88-a5d1-738c054512b5:card_description', 'rollback of teaser-card-s005: card_description ''Remains in Velika Balanica make it one of the oldest localities in Europe where transition from the Lower to Middle Paleolithic is recorded.'' restored on Balanica', '9d3197631184f89442b5c0aaf7f0fe553853880b4ab1e88e1cc253c9f8bc8251|82723c73a750635ad08926c0789948769ba5791689217157bb97fb23ecf85c36|82723c73a750635ad08926c0789948769ba5791689217157bb97fb23ecf85c36', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In 2006 the Balanica caves gave up half a hominin jaw, the first hominin specimen in the Central Balkans recovered through controlled excavations with firm stratigraphic context."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the find was made in 2006 [S5]; the find came from the Balanica caves [S2, S5]; the find is half a hominin jaw (hemi-mandible) [S5]; it is the first hominin specimen in the Central Balkans recovered through controlled excavations with firm stratigraphic context [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Balanica is a cave site (a complex of caves) in Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Balanica]; The hominin jaw was found in 2006 [SUPPORTED: https://en.wikipedia.org/wiki/Balanica]; The find is half a hominin jaw (a hemi-mandible) [SUPPORTED: https://en.wikipedia.org/wiki/Balanica]; It is the first hominin specimen in the Central Balkans recovered through controlled excavations with firm stratigraphic context [SUPPORTED: https://en.wikipedia.org/wiki/Balanica]"}]'::jsonb),
    ('da471a32-1170-4d29-a63e-495436f6e326'::uuid, 'card_description', 'Cut into marlstone with stone tools, the Artificial Caves of Alapraia end in round chambers under skylights, believed to have let bodies in when the corridors could no longer be used.', 'A Neolithic necropolis from the 4th millennium BC with burial chambers cut into solid rock. These artificial caves mimic natural cave burials but in controlled, purpose-built spaces.', 'teaser-card-s005-rollback:da471a32-1170-4d29-a63e-495436f6e326:card_description', 'rollback of teaser-card-s005: card_description ''A Neolithic necropolis from the 4th millennium BC with burial chambers cut into solid rock. These artificial caves mimic natural cave burials but in controlled, purpose-built spaces.'' restored on Artificial Caves of Alapraia', '52771b5b548b68a5b64aa6796e090248f29b9266bd85c355a3450bafb567da95|67ad5cf74fd4e2528b456a73b91cd60ce7c9171ac255b69c3a5f61ba96f39030|67ad5cf74fd4e2528b456a73b91cd60ce7c9171ac255b69c3a5f61ba96f39030', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Cut into marlstone with stone tools, the Artificial Caves of Alapraia end in round chambers under skylights, believed to have let bodies in when the corridors could no longer be used."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the caves were cut into marlstone [S1]; they were cut with stone tools [S1]; each ends in a round chamber [S3]; the chambers have skylights at the top [S3]; the skylights are believed to have allowed bodies to be placed in the chamber when the corridor could no longer be used for access [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Artificial Caves of Alapraia are prehistoric rock-cut burial caves (hypogea) in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Alapraia]; They lie in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Alapraia]; They were cut into marlstone [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Alapraia]; They were cut with stone tools [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Alapraia]; Each is reached through a corridor and ends in a round chamber [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Alapraia]; The chambers lie under skylights [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Alapraia]; The skylights are believed to have let bodies in when the corridors could no longer be used [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Alapraia]"}]'::jsonb),
    ('db227639-34b4-45db-817c-95092b4a916a'::uuid, 'card_description', 'In Lima''s San Isidro district rises Huaca Huallamarca, a truncated stepped pyramid of small handmade adobes shaped like molars, its building begun by the Huallas from 200 BC to AD 200.', 'The construction of the Huallamarca pyramid began with the Huallas from 200 BC to AD 200.', 'teaser-card-s005-rollback:db227639-34b4-45db-817c-95092b4a916a:card_description', 'rollback of teaser-card-s005: card_description ''The construction of the Huallamarca pyramid began with the Huallas from 200 BC to AD 200.'' restored on Huaca Huallamarca', 'ab45dc661f95ef2ebc5daadb7eb195ac8133b16b0fe89f00463ee3f7e5c74caf|c1caa3807d07c064bcf9b4fb21b03381b3fc8006eed6d72c8744ab888a13473f|c1caa3807d07c064bcf9b4fb21b03381b3fc8006eed6d72c8744ab888a13473f', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In Lima''s San Isidro district rises Huaca Huallamarca, a truncated stepped pyramid of small handmade adobes shaped like molars, its building begun by the Huallas from 200 BC to AD 200."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Huaca Huallamarca is in the San Isidro district of Lima [S1]; it is a truncated stepped pyramid [S2]; it is built of small handmade adobes [S6]; the adobes are shaped like molars [S6]; its construction was begun by the Huallas [S5]; construction began from 200 BC to AD 200 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Huaca Huallamarca is an archaeological site (a pyramid mound) in the San Isidro district of Lima, Peru [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huallamarca]; It is a truncated stepped pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huallamarca]; It is built of small handmade adobes [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huallamarca]; The adobes are shaped like molars [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huallamarca]; Its building was begun by the Huallas [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huallamarca]; This first building phase dates from 200 BC to AD 200 [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Huallamarca]"}]'::jsonb),
    ('db3840fb-0dfd-444c-be07-ed15ee4874cc'::uuid, 'card_description', 'In 1879 a farmer making holes for a sheep pen struck a buried mosaic floor: Brading Roman Villa, whose luxurious rooms held fine mosaics, Samian pottery, jewellery and games.', 'The first simple villa dates from the mid-1st century but it developed into a large and impressive stone-built villa around three sides of a central courtyard.', 'teaser-card-s005-rollback:db3840fb-0dfd-444c-be07-ed15ee4874cc:card_description', 'rollback of teaser-card-s005: card_description ''The first simple villa dates from the mid-1st century but it developed into a large and impressive stone-built villa around three sides of a central courtyard.'' restored on Brading Roman Villa', '4ba1557543cea6eadd1a4b98c47901ca52bc9c9d5eb0b0a9196a9b70e74d864c|e622edaf0c234164fc2a8433869d0f79bb9c47f4e2f06a4be5263b668e1089e9|e622edaf0c234164fc2a8433869d0f79bb9c47f4e2f06a4be5263b668e1089e9', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "In 1879 a farmer making holes for a sheep pen struck a buried mosaic floor: Brading Roman Villa, whose luxurious rooms held fine mosaics, Samian pottery, jewellery and games."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "in 1879 a farmer struck a buried mosaic floor [S2]; he was making holes for a sheep pen [S2]; Brading Roman Villa had luxurious rooms [S4]; its rooms held fine mosaics [S4]; Samian pottery, jewellery and games were found in the house [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Brading Roman Villa is a Roman villa (in England, at Brading on the Isle of Wight) [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; It was discovered in 1879 [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; The discoverer was a farmer [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; He was making holes for a sheep pen [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; He struck a buried mosaic floor [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; The villa had luxurious rooms [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; The rooms held fine mosaics [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; Samian pottery was found in the villa [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; Jewellery was found in the villa [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]; Games were found in the villa [SUPPORTED: https://en.wikipedia.org/wiki/Brading_Roman_Villa]"}]'::jsonb),
    ('db85cd62-288f-4142-9cad-f15532e4fe26'::uuid, 'card_description', 'Along the riverbank ran the Pannonian Limes, a Roman frontier of camps, watchtowers and fortified bridgeheads that guarded the Pannonian provinces against attacks from the north.', 'A 420 km stretch of Roman frontier fortifications along the Danube, defended from the time of Augustus to the 5th century AD. Forts lined the river at regular intervals.', 'teaser-card-s005-rollback:db85cd62-288f-4142-9cad-f15532e4fe26:card_description', 'rollback of teaser-card-s005: card_description ''A 420 km stretch of Roman frontier fortifications along the Danube, defended from the time of Augustus to the 5th century AD. Forts lined the river at regular intervals.'' restored on Pannonian Limes', 'bd71d175afe774da90b870b74859f3e1b60d57d8c88c09fa94b797ff92cd5b44|73fcefded5bbd424d0f9a20417c0bf5724055fe84ae34efa2d1437c97457225c|73fcefded5bbd424d0f9a20417c0bf5724055fe84ae34efa2d1437c97457225c', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Along the riverbank ran the Pannonian Limes, a Roman frontier of camps, watchtowers and fortified bridgeheads that guarded the Pannonian provinces against attacks from the north."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the Pannonian Limes is a Roman frontier [S1]; its works stood along the riverbank [S4]; it consisted of camps, watchtowers and fortified bridgeheads [S4]; it protected the Pannonian provinces against attacks from the north [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Pannonian Limes is a Roman frontier (a fortified military border) [SUPPORTED: https://en.wikipedia.org/wiki/Pannonian_Limes]; It ran along the riverbank [SUPPORTED: https://en.wikipedia.org/wiki/Pannonian_Limes]; It consisted of camps [SUPPORTED: https://en.wikipedia.org/wiki/Pannonian_Limes]; It had watchtowers [SUPPORTED: https://en.wikipedia.org/wiki/Pannonian_Limes]; It had fortified bridgeheads [SUPPORTED: https://en.wikipedia.org/wiki/Pannonian_Limes]; It guarded the Pannonian provinces [SUPPORTED: https://en.wikipedia.org/wiki/Pannonian_Limes]; The threat it guarded against came from the north [SUPPORTED: https://en.wikipedia.org/wiki/Pannonian_Limes]"}]'::jsonb),
    ('dc277dc8-5631-484f-b07a-d1462403dd92'::uuid, 'card_description', 'On a small knoll in Northumberland, The Poind and his Man joins a round cairn to a standing stone 2 metres tall; a stone at Wallington Hall is thought to have been moved from here.', 'The Poind and his Man is a prehistoric site in Northumberland near the village of Bolam and about 7 miles west of Morpeth.', 'teaser-card-s005-rollback:dc277dc8-5631-484f-b07a-d1462403dd92:card_description', 'rollback of teaser-card-s005: card_description ''The Poind and his Man is a prehistoric site in Northumberland near the village of Bolam and about 7 miles west of Morpeth.'' restored on The Poind and his Man', 'd4dda721e361ce04d49d6670f1b1d6ca6b238e755de2597a7cd8d562abfadcc5|c4b21d6492d1c9d69635142901fbfe14603bc26e1d588533019ba742194fedd8|c4b21d6492d1c9d69635142901fbfe14603bc26e1d588533019ba742194fedd8', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "On a small knoll in Northumberland, The Poind and his Man joins a round cairn to a standing stone 2 metres tall; a stone at Wallington Hall is thought to have been moved from here."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "the site is on a small knoll [S3]; it is in Northumberland [S1]; it consists of a round cairn and a standing stone [S2, S3]; the standing stone is 2 metres tall [S6]; a stone at Wallington Hall is thought to have been moved from here [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Poind and his Man is a prehistoric monument site (a burial cairn with a standing stone) in Northumberland [SUPPORTED: https://en.wikipedia.org/wiki/The_Poind_and_his_Man]; It lies on a small knoll [SUPPORTED: https://en.wikipedia.org/wiki/The_Poind_and_his_Man]; It includes a round cairn [SUPPORTED: https://en.wikipedia.org/wiki/The_Poind_and_his_Man]; It includes a standing stone beside the cairn [SUPPORTED: https://en.wikipedia.org/wiki/The_Poind_and_his_Man]; The standing stone is 2 metres tall [SUPPORTED: https://en.wikipedia.org/wiki/The_Poind_and_his_Man]; A stone at Wallington Hall is thought to have been moved from this site [SUPPORTED: https://en.wikipedia.org/wiki/The_Poind_and_his_Man]"}]'::jsonb),
    ('dce4d9db-1bf4-4430-b5e6-2e13e63e4813'::uuid, 'card_description', 'Legend says a man of immense size sharpened his scythe on the Verziau of Gargantua and left it here in anger. The menhir''s twin sister was destroyed for its sandstone.', 'A 4.35-meter sandstone monolith at Bois-lès-Pargny, dating to around 3500 BC. A twin menhir was demolished for building material in the 19th century; legend links both stones to the giant Gargantua.', 'teaser-card-s005-rollback:dce4d9db-1bf4-4430-b5e6-2e13e63e4813:card_description', 'rollback of teaser-card-s005: card_description ''A 4.35-meter sandstone monolith at Bois-lès-Pargny, dating to around 3500 BC. A twin menhir was demolished for building material in the 19th century; legend links both stones to the giant Gargantua.'' restored on Verziau of Gargantua', '3d251c724ea16cbceba7e70e0dce7e7ecc9e9ef76278dd72c371be620b25ce48|41b3614a788f577e0d2cec5e3d7fe11bf70afa8f1a237ceafa0f79f5f08ac422|41b3614a788f577e0d2cec5e3d7fe11bf70afa8f1a237ceafa0f79f5f08ac422', '[{"source": "lane WB run wb-ws-2026-09-27-03: writer teaser-wb-ws-2026-09-27-03-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "Legend says a man of immense size sharpened his scythe on the Verziau of Gargantua and left it here in anger. The menhir''s twin sister was destroyed for its sandstone."}, {"source": "lane WB run wb-ws-2026-09-27-03: checker teaser-wb-ws-2026-09-27-03-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "legend says a man of immense size sharpened his scythe on the stone [S4]; legend says he left it on the site in anger [S4]; the Verziau of Gargantua is a menhir [S1]; the menhir had a twin sister [S3]; the twin was destroyed to extract its sandstone [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-03: verifier teaser-wb-ws-2026-09-27-03-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-03/OUTCOMES.jsonl", "quote": "The Verziau of Gargantua is a menhir (a prehistoric standing stone) in France [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]; A legend is told about the stone [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]; In the legend the protagonist is a man of immense size [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]; In the legend he sharpened his scythe on the stone [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]; In the legend he left the stone at this spot in anger [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]; The menhir had a twin sister (a second menhir) [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]; The twin was destroyed [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]; The twin was destroyed for its sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Verziau_of_Gargantua]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s005-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s005-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s005-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s005-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s005-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
